BEGIN;

-- ---- pocheon-sanjeong-lake-herb-island-art-valley [en] --------------------------------------
UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"catalog_card","badges"}', '["Seoul day trip","Mon · Thu · Sat","UNESCO Geopark","Waterfall","Lake walk","Small group"]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'en'
  AND detail_payload #> '{"catalog_card","badges"}' IS NOT DISTINCT FROM '["Seoul day trip","UNESCO Geopark","Waterfall","Lake walk","Small group"]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"catalog_card","shortCardDescription"}', '"A calmer Seoul day-trip built on real geology. Walk the flat 3.2 km loop around Sanjeong Lake under Myeongseongsan, eat Pocheon''s own Idong galbi, then cross an 80 m suspension bridge to face Jaein Falls as it drops 18 m over basalt columns, and finish inside Pocheon Art Valley''s granite quarry, where spring water has filled the pit into the emerald Cheonjuho. Jaein Falls and Art Valley are both geosites of the Hantangang UNESCO Global Geopark — the same landscape seen from its two opposite halves. Departs Mondays, Thursdays and Saturdays."'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'en'
  AND detail_payload #>> '{"catalog_card","shortCardDescription"}' IS NOT DISTINCT FROM 'A calmer Seoul day-trip built on real geology. Walk the flat 3.2 km loop around Sanjeong Lake under Myeongseongsan, eat Pocheon''s own Idong galbi, then cross an 80 m suspension bridge to face Jaein Falls as it drops 18 m over basalt columns, and finish inside Pocheon Art Valley''s granite quarry, where spring water has filled the pit into the emerald Cheonjuho. Jaein Falls and Art Valley are both geosites of the Hantangang UNESCO Global Geopark — the same landscape seen from its two opposite halves.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"whyTourWorks","lessIdealFor"}', '["Travelers wanting a shopping-heavy or high-energy day","Anyone needing a fully indoor rainy-day plan","Visitors set on famous single landmarks (try Suwon Hwaseong instead)","Groups needing step-free access at every stop","Travellers who can''t travel on a Monday, Thursday or Saturday (the only departure days)"]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'en'
  AND detail_payload #> '{"whyTourWorks","lessIdealFor"}' IS NOT DISTINCT FROM '["Travelers wanting a shopping-heavy or high-energy day","Anyone needing a fully indoor rainy-day plan","Visitors set on famous single landmarks (try Suwon Hwaseong instead)","Groups needing step-free access at every stop"]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"Departure days","preview":"This tour departs **on Mondays, Thursdays and Saturdays only** — please book one of those dates.","content":["This tour departs **on Mondays, Thursdays and Saturdays only** — please book one of those dates.","The route, the timings and both pickup points are identical on all three departure days.","If your dates don''t include a Monday, Thursday or Saturday, the tour can''t be moved to another day — it is a fixed-schedule small-group departure, not a private charter."]},{"id":"pickup","title":"Pickup & drop-off","preview":"Two pickup points: Hongik University Station Exit 8 (08:00) and Myeongdong Station Exit 2 (08:30).","content":["Two pickup points: Hongik University Station Exit 8 (08:00) and Myeongdong Station Exit 2 (08:30).","Please arrive at your meeting point 10 minutes before the departure time.","Your guide waits at the station exit with the bus.","Drop-off reverses the order: Myeongdong around 18:00, Hongik University Station around 18:30.","Return times are approximate and depend on traffic.","This is a fixed-route group format; travellers reach the meeting point themselves."]},{"id":"walking","title":"Walking & terrain","preview":"Moderate overall — about 5–6 km across the day, with short demanding sections.","content":["Moderate overall — about 5–6 km across the day, with short demanding sections.","Sanjeong Lake: flat 3.2 km loop, no uphill, 60–90 min.","Jaein Falls: the 80 m suspension bridge is flat but sways; the boardwalk down toward the pool has stairs both ways.","Pocheon Art Valley: steep from base to rim — the monorail covers it; the Healing Forest walk down is 10–15 min.","No hiking and no summit climb is included at any stop.","Comfortable closed shoes recommended; the gorge boardwalk can be wet."]},{"id":"weather","title":"Weather policy","preview":"Strong seasonal variety; substitutions are common","content":["Spring (Mar–May): Mist lifts off Sanjeong Lake on cool mornings, and snowmelt keeps Jaein Falls running strongly. Cheonjuho reads its clearest emerald as the light lengthens.","Summer (Jun–Aug): The falls are at their most powerful, and the gorge stays several degrees cooler than the city. Heavy monsoon rain can close the Jaein Falls deck sections — the one weather risk on this route.","Autumn (Sep–Nov): The strongest season here. Silver grass turns the Myeongseongsan slopes silver-white through October, the lake carries the year''s best reflections, and Art Valley''s granite walls sit inside full foliage.","Winter (Dec–Feb): Quietest crowds of the year. Cheonjuho can freeze over, the lake hosts its sledding festival, and the falls may partly ice. Daylight is short, so the afternoon runs tighter and the Jaein boardwalk can be slippery.","Light rain: tour usually proceeds; heavy rain may shorten outdoor stops"]},{"id":"wear","title":"What to wear & bring","preview":"Walking shoes, layers, and seasonal extras","content":["Comfortable walking shoes with grip","Layered clothing for mountain temperature changes","Light jacket or windbreaker (cooler than central Seoul, especially at Sanjeong Lake)","Sun protection in summer; warm jacket and gloves in winter","Camera or phone for the strong photo opportunities at all three stops"]},{"id":"included","title":"What''s included","preview":"Round-trip transport from central Seoul, licensed English-speaking guide, fuel, tolls and parking.","variant":"included","content":["Round-trip transport from central Seoul, licensed English-speaking guide, fuel, tolls and parking.","Free-admission stops: Sanjeong Lake and its loop trail, Jaein Falls, the suspension bridge and skywalk.","Not included — Pocheon Art Valley admission (≈ ₩6,000 adult) and monorail (≈ ₩5,300 adult round trip), 2026 rates.","Not included — lunch (≈ ₩15,000–20,000), drinks, personal spending and tips."]},{"id":"geopark","title":"About the UNESCO Global Geopark","preview":"Two of today''s stops are designated geosites.","content":["The Hantangang UNESCO Global Geopark was certified on 7 July 2020 by UNESCO''s 209th Executive Board in Paris, and re-designated in 2024. It covers the Hantangang river basin across Pocheon and Yeoncheon in Gyeonggi-do and Cheorwon in Gangwon-do.","Jaein Falls is a geosite: an ≈18 m waterfall over basalt columnar joints, with a river-cut cave, potholes and gas tubes readable at its base.","Pocheon Art Valley is a geosite listed as ''Art Valley and Pocheon Stone'': the ancient granite basement rock that the Hantangang lava later flowed across.","A UNESCO Global Geopark is a geological designation — it is not the same as a UNESCO World Heritage listing."]},{"id":"cancellation","title":"Cancellation","preview":"Free cancellation up to 24 hours before the tour starts.","content":["Free cancellation up to 24 hours before the tour starts.","Same-day cancellations and no-shows are non-refundable."]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'en'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"Pickup & drop-off","content":["Two pickup points: Hongik University Station Exit 8 (08:00) and Myeongdong Station Exit 2 (08:30).","Please arrive at your meeting point 10 minutes before the departure time.","Your guide waits at the station exit with the bus.","Drop-off reverses the order: Myeongdong around 18:00, Hongik University Station around 18:30.","Return times are approximate and depend on traffic.","This is a fixed-route group format; travellers reach the meeting point themselves."],"preview":"Two pickup points: Hongik University Station Exit 8 (08:00) and Myeongdong Station Exit 2 (08:30)."},{"id":"walking","title":"Walking & terrain","content":["Moderate overall — about 5–6 km across the day, with short demanding sections.","Sanjeong Lake: flat 3.2 km loop, no uphill, 60–90 min.","Jaein Falls: the 80 m suspension bridge is flat but sways; the boardwalk down toward the pool has stairs both ways.","Pocheon Art Valley: steep from base to rim — the monorail covers it; the Healing Forest walk down is 10–15 min.","No hiking and no summit climb is included at any stop.","Comfortable closed shoes recommended; the gorge boardwalk can be wet."],"preview":"Moderate overall — about 5–6 km across the day, with short demanding sections."},{"id":"weather","title":"Weather policy","content":["Spring (Mar–May): Mist lifts off Sanjeong Lake on cool mornings, and snowmelt keeps Jaein Falls running strongly. Cheonjuho reads its clearest emerald as the light lengthens.","Summer (Jun–Aug): The falls are at their most powerful, and the gorge stays several degrees cooler than the city. Heavy monsoon rain can close the Jaein Falls deck sections — the one weather risk on this route.","Autumn (Sep–Nov): The strongest season here. Silver grass turns the Myeongseongsan slopes silver-white through October, the lake carries the year''s best reflections, and Art Valley''s granite walls sit inside full foliage.","Winter (Dec–Feb): Quietest crowds of the year. Cheonjuho can freeze over, the lake hosts its sledding festival, and the falls may partly ice. Daylight is short, so the afternoon runs tighter and the Jaein boardwalk can be slippery.","Light rain: tour usually proceeds; heavy rain may shorten outdoor stops"],"preview":"Strong seasonal variety; substitutions are common"},{"id":"wear","title":"What to wear & bring","content":["Comfortable walking shoes with grip","Layered clothing for mountain temperature changes","Light jacket or windbreaker (cooler than central Seoul, especially at Sanjeong Lake)","Sun protection in summer; warm jacket and gloves in winter","Camera or phone for the strong photo opportunities at all three stops"],"preview":"Walking shoes, layers, and seasonal extras"},{"id":"included","title":"What''s included","content":["Round-trip transport from central Seoul, licensed English-speaking guide, fuel, tolls and parking.","Free-admission stops: Sanjeong Lake and its loop trail, Jaein Falls, the suspension bridge and skywalk.","Not included — Pocheon Art Valley admission (≈ ₩6,000 adult) and monorail (≈ ₩5,300 adult round trip), 2026 rates.","Not included — lunch (≈ ₩15,000–20,000), drinks, personal spending and tips."],"preview":"Round-trip transport from central Seoul, licensed English-speaking guide, fuel, tolls and parking.","variant":"included"},{"id":"geopark","title":"About the UNESCO Global Geopark","content":["The Hantangang UNESCO Global Geopark was certified on 7 July 2020 by UNESCO''s 209th Executive Board in Paris, and re-designated in 2024. It covers the Hantangang river basin across Pocheon and Yeoncheon in Gyeonggi-do and Cheorwon in Gangwon-do.","Jaein Falls is a geosite: an ≈18 m waterfall over basalt columnar joints, with a river-cut cave, potholes and gas tubes readable at its base.","Pocheon Art Valley is a geosite listed as ''Art Valley and Pocheon Stone'': the ancient granite basement rock that the Hantangang lava later flowed across.","A UNESCO Global Geopark is a geological designation — it is not the same as a UNESCO World Heritage listing."],"preview":"Two of today''s stops are designated geosites."},{"id":"cancellation","title":"Cancellation","content":["Free cancellation up to 24 hours before the tour starts.","Same-day cancellations and no-shows are non-refundable."],"preview":"Free cancellation up to 24 hours before the tour starts."}]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"staticQuestions"}', '[{"question":"What changed on this tour — didn''t it include Herb Island?","answer":"It did. From August 2026 the route swaps Herb Island for Jaein Falls in Yeoncheon and adds a proper local lunch stop. The reason is that Jaein Falls and Pocheon Art Valley are both geosites of the Hantangang UNESCO Global Geopark, so the day now tells one connected geological story instead of three unrelated stops. If you specifically want Herb Island, contact us before booking — we run it as a separate arrangement."},{"question":"Which days of the week does this tour run?","answer":"It runs **on Mondays, Thursdays and Saturdays only**. The itinerary is the same on all three days, so book whichever one fits your trip. Other weekdays are not available on this product."},{"question":"What makes Jaein Falls and Art Valley ''UNESCO''?","answer":"Both are designated geosites of the Hantangang UNESCO Global Geopark, certified on 7 July 2020 and re-designated in 2024. It is a geopark designation, not a World Heritage listing — it recognises the geology of the Hantangang river basin across Pocheon, Yeoncheon and Cheorwon. Jaein Falls shows the basalt lava and its columnar joints; Art Valley shows the ancient granite basement the lava flowed over."},{"question":"Is the suspension bridge at Jaein Falls scary? Can I skip it?","answer":"It is 80 m long and 2 m wide and it does sway underfoot by design — that is the appeal for most guests. You can skip it entirely: the rim viewpoint sees the waterfall without crossing, and the boardwalk toward the pool is a separate path. Nobody is left behind if you''d rather stay on solid ground."},{"question":"Is admission included?","answer":"Sanjeong Lake and Jaein Falls are both free. Pocheon Art Valley is not included — roughly ₩6,000 admission plus about ₩5,300 for an adult monorail round trip in 2026, with lower youth, military and child rates. Lunch is also not included (≈ ₩15,000–20,000). Everything else — transport, guide, tolls and parking — is covered."},{"question":"How much walking is there, and how hard is it?","answer":"About 5–6 km across the day, most of it the flat 3.2 km lake loop in the morning. Jaein Falls has stairs on the boardwalk down toward the pool. Art Valley is steep from the base to the rim, which the monorail solves — you ride up and walk down through the forest. There is no hiking and no summit climb on this tour."},{"question":"Is lunch included, and what are the options?","answer":"Not included, about ₩15,000–20,000. Lunch is in Idong, the Pocheon district that gives Idong galbi (beef short ribs) its name. Mushroom dishes and uleong — freshwater snail — are the other local specialities, and Idong makgeolli is brewed in the same valley. Tell your guide if you need vegetarian options and they''ll point you to the right table."},{"question":"How is this different from a Nami Island day-trip?","answer":"Nami Island is a single, very popular destination reached by ferry. This route is three genuinely different landscapes — a century-old reservoir, a basalt waterfall gorge and a flooded granite quarry — in a part of Gyeonggi that sees a fraction of Nami''s crowds, with a UNESCO Global Geopark thread running through the afternoon."},{"question":"Is this worthwhile in winter?","answer":"Yes, with trade-offs. Cheonjuho freezing over at Art Valley is one of the site''s best sights, the lake hosts a sledding festival, and every stop is at its quietest. Against that: daylight is short, so the afternoon runs tighter, and the Jaein Falls boardwalk can be icy. Dress properly and it''s a strong winter day."},{"question":"What happens if it rains?","answer":"The tour runs. The lake loop and Art Valley are fine with an umbrella, and rain actually strengthens Jaein Falls. The one real exception is heavy summer rain, when the deck sections at the gorge can be closed for safety — in that case we extend the other stops rather than cancel the day."},{"question":"Where do you pick up and drop off?","answer":"Two Seoul meeting points: Hongik University Station Exit 8 at 08:00 and Myeongdong Station Exit 2 at 08:30. Please arrive 10 minutes before your departure time — the guide waits at the exit with the bus. The return reverses the order: Myeongdong around 18:00 and Hongik University Station around 18:30, depending on traffic."},{"question":"Is this suitable for children or older adults?","answer":"For most, yes. The lake loop is flat and the monorail removes Art Valley''s climb. The two things to weigh are the Jaein Falls boardwalk stairs and the swaying suspension bridge — both are optional, and the rim viewpoint gives the waterfall to anyone who''d rather not. It is a 10-hour day, so it suits active older travellers better than anyone needing frequent rest."},{"question":"Can I do this by public transport instead?","answer":"It would be difficult. Sanjeong Lake, Jaein Falls and Art Valley sit in three different districts across two counties, and buses to Art Valley run only every couple of hours. Doing all three in a day without a vehicle is not realistic — which is most of the reason this route exists as a tour."}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'en'
  AND detail_payload #> '{"staticQuestions"}' IS NOT DISTINCT FROM '[{"answer":"It did. From August 2026 the route swaps Herb Island for Jaein Falls in Yeoncheon and adds a proper local lunch stop. The reason is that Jaein Falls and Pocheon Art Valley are both geosites of the Hantangang UNESCO Global Geopark, so the day now tells one connected geological story instead of three unrelated stops. If you specifically want Herb Island, contact us before booking — we run it as a separate arrangement.","question":"What changed on this tour — didn''t it include Herb Island?"},{"answer":"Both are designated geosites of the Hantangang UNESCO Global Geopark, certified on 7 July 2020 and re-designated in 2024. It is a geopark designation, not a World Heritage listing — it recognises the geology of the Hantangang river basin across Pocheon, Yeoncheon and Cheorwon. Jaein Falls shows the basalt lava and its columnar joints; Art Valley shows the ancient granite basement the lava flowed over.","question":"What makes Jaein Falls and Art Valley ''UNESCO''?"},{"answer":"It is 80 m long and 2 m wide and it does sway underfoot by design — that is the appeal for most guests. You can skip it entirely: the rim viewpoint sees the waterfall without crossing, and the boardwalk toward the pool is a separate path. Nobody is left behind if you''d rather stay on solid ground.","question":"Is the suspension bridge at Jaein Falls scary? Can I skip it?"},{"answer":"Sanjeong Lake and Jaein Falls are both free. Pocheon Art Valley is not included — roughly ₩6,000 admission plus about ₩5,300 for an adult monorail round trip in 2026, with lower youth, military and child rates. Lunch is also not included (≈ ₩15,000–20,000). Everything else — transport, guide, tolls and parking — is covered.","question":"Is admission included?"},{"answer":"About 5–6 km across the day, most of it the flat 3.2 km lake loop in the morning. Jaein Falls has stairs on the boardwalk down toward the pool. Art Valley is steep from the base to the rim, which the monorail solves — you ride up and walk down through the forest. There is no hiking and no summit climb on this tour.","question":"How much walking is there, and how hard is it?"},{"answer":"Not included, about ₩15,000–20,000. Lunch is in Idong, the Pocheon district that gives Idong galbi (beef short ribs) its name. Mushroom dishes and uleong — freshwater snail — are the other local specialities, and Idong makgeolli is brewed in the same valley. Tell your guide if you need vegetarian options and they''ll point you to the right table.","question":"Is lunch included, and what are the options?"},{"answer":"Nami Island is a single, very popular destination reached by ferry. This route is three genuinely different landscapes — a century-old reservoir, a basalt waterfall gorge and a flooded granite quarry — in a part of Gyeonggi that sees a fraction of Nami''s crowds, with a UNESCO Global Geopark thread running through the afternoon.","question":"How is this different from a Nami Island day-trip?"},{"answer":"Yes, with trade-offs. Cheonjuho freezing over at Art Valley is one of the site''s best sights, the lake hosts a sledding festival, and every stop is at its quietest. Against that: daylight is short, so the afternoon runs tighter, and the Jaein Falls boardwalk can be icy. Dress properly and it''s a strong winter day.","question":"Is this worthwhile in winter?"},{"answer":"The tour runs. The lake loop and Art Valley are fine with an umbrella, and rain actually strengthens Jaein Falls. The one real exception is heavy summer rain, when the deck sections at the gorge can be closed for safety — in that case we extend the other stops rather than cancel the day.","question":"What happens if it rains?"},{"answer":"Two Seoul meeting points: Hongik University Station Exit 8 at 08:00 and Myeongdong Station Exit 2 at 08:30. Please arrive 10 minutes before your departure time — the guide waits at the exit with the bus. The return reverses the order: Myeongdong around 18:00 and Hongik University Station around 18:30, depending on traffic.","question":"Where do you pick up and drop off?"},{"answer":"For most, yes. The lake loop is flat and the monorail removes Art Valley''s climb. The two things to weigh are the Jaein Falls boardwalk stairs and the swaying suspension bridge — both are optional, and the rim viewpoint gives the waterfall to anyone who''d rather not. It is a 10-hour day, so it suits active older travellers better than anyone needing frequent rest.","question":"Is this suitable for children or older adults?"},{"answer":"It would be difficult. Sanjeong Lake, Jaein Falls and Art Valley sit in three different districts across two counties, and buses to Art Valley run only every couple of hours. Doing all three in a day without a vehicle is not realistic — which is most of the reason this route exists as a tour.","question":"Can I do this by public transport instead?"}]'::jsonb;

