UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"출발 요일","preview":"이 투어는 **월요일·목요일·토요일에만 출발합니다** — 세 요일 중 하루로 예약해 주세요.","content":["이 투어는 **월요일·목요일·토요일에만 출발합니다** — 세 요일 중 하루로 예약해 주세요.","세 출발일 모두 코스와 시간, 두 곳의 픽업 장소가 동일합니다.","여행 일정에 월·목·토가 없다면 다른 요일로 옮길 수 없습니다. 개인 전세 차량이 아니라 정해진 일정으로 운행하는 소규모 그룹 투어이기 때문입니다."]},{"id":"pickup","title":"픽업 및 드롭오프","preview":"픽업 장소는 두 곳입니다: 홍대입구역 8번 출구(08:00), 명동역 2번 출구(08:30).","content":["픽업 장소는 두 곳입니다: 홍대입구역 8번 출구(08:00), 명동역 2번 출구(08:30).","출발 시각 10분 전까지 미팅 포인트에 도착해 주시기 바랍니다.","가이드가 버스와 함께 역 출구에서 기다립니다.","드롭오프는 역순입니다. 명동 18:00쯤, 홍대입구역 18:30쯤.","귀경 시각은 대략이며 교통 상황에 따라 달라집니다.","고정 노선 그룹 투어이며, 미팅 포인트까지는 여행자가 직접 오셔야 합니다."]},{"id":"walking","title":"도보와 지형","preview":"전체적으로 보통 수준 — 하루 약 5–6 km이며 짧게 힘든 구간이 섞여 있습니다.","content":["전체적으로 보통 수준 — 하루 약 5–6 km이며 짧게 힘든 구간이 섞여 있습니다.","산정호수: 평탄한 3.2 km 순환 코스, 오르막 없음, 60–90분.","재인폭포: 80 m 출렁다리는 평지지만 흔들립니다. 소 쪽으로 내려가는 데크길은 오르내림 모두 계단입니다.","포천 아트밸리: 아래에서 능선까지 가파르지만 모노레일이 해결합니다. 힐링 숲길로 내려오는 데 10–15분.","어느 스팟에도 등산이나 정상 등반은 포함되지 않습니다.","발이 편한 앞이 막힌 신발을 권합니다. 협곡 데크길은 젖어 있을 수 있습니다."]},{"id":"weather","title":"날씨 정책","preview":"계절별 변화가 뚜렷하며, 대체 일정이 발생할 수 있습니다","content":["봄 (3–5월): 쌀쌀한 아침이면 산정호수 위로 물안개가 피어오르고, 눈 녹은 물이 재인폭포를 힘차게 흐르게 합니다. 해가 길어지면서 천주호의 에메랄드빛도 가장 맑게 보입니다.","여름 (6–8월): 폭포가 가장 힘찬 계절이고, 협곡은 도심보다 몇 도쯤 서늘합니다. 장마철 폭우 때는 재인폭포 데크 구간이 통제될 수 있는데, 이 코스의 유일한 날씨 변수입니다.","가을 (9–11월): 이곳이 가장 좋은 계절입니다. 10월 내내 억새가 명성산 비탈을 은백색으로 물들이고, 호수에는 한 해 중 가장 아름다운 반영이 담기며, 아트밸리의 화강암 절벽은 단풍 한가운데에 놓입니다.","겨울 (12–2월): 한 해 중 가장 한적합니다. 천주호가 얼어붙기도 하고, 호수에서는 눈썰매 축제가 열리며, 폭포도 일부 얼 수 있습니다. 해가 짧아 오후 일정이 조금 빠듯해지고 재인폭포 데크길이 미끄러울 수 있습니다.","가벼운 비: 투어는 대체로 정상 진행; 폭우 시 야외 일정이 단축될 수 있습니다"]},{"id":"wear","title":"복장 및 준비물","preview":"워킹화, 레이어드 의류, 계절별 추가 준비물","content":["미끄럼 방지 기능이 있는 편안한 워킹화","산악 기온 변화에 대비한 레이어드 의류","가벼운 재킷 또는 바람막이 (서울 도심보다 기온이 낮으며, 특히 산정호수 주변)","여름철 자외선 차단 용품; 겨울철 따뜻한 재킷과 장갑","세 곳 모두 사진 촬영 명소이므로 카메라 또는 휴대폰 준비"]},{"id":"included","title":"포함 사항","preview":"서울 도심 왕복 차량, 자격을 갖춘 영어 가이드, 유류비, 통행료, 주차료.","variant":"포함","content":["서울 도심 왕복 차량, 자격을 갖춘 영어 가이드, 유류비, 통행료, 주차료.","무료 입장 스팟: 산정호수와 둘레길, 재인폭포, 출렁다리와 스카이워크.","불포함 — 포천 아트밸리 입장료(성인 약 ₩6,000)와 모노레일(성인 왕복 약 ₩5,300), 2026년 기준.","불포함 — 점심(약 ₩15,000–20,000), 음료, 개인 경비, 팁."]},{"id":"geopark","title":"유네스코 세계지질공원에 대하여","preview":"오늘 방문하는 스팟 중 두 곳이 지정 지질명소입니다.","content":["한탄강 유네스코 세계지질공원은 2020년 7월 7일 파리에서 열린 유네스코 제209차 집행이사회에서 인증됐고, 2024년 재인증됐습니다. 경기도 포천과 연천, 강원도 철원에 걸친 한탄강 유역을 아우릅니다.","재인폭포는 지질명소입니다. 현무암 주상절리 위로 떨어지는 약 18 m 폭포이며, 그 아래에서 강이 깎아낸 하식동굴과 포트홀, 가스튜브를 읽을 수 있습니다.","포천 아트밸리는 ''아트밸리와 포천석''이라는 이름으로 등재된 지질명소로, 훗날 한탄강 용암이 그 위로 흘러간 오래된 화강암 기반암입니다.","유네스코 세계지질공원은 지질학적 가치에 대한 지정이며, 유네스코 세계유산 등재와는 다릅니다."]},{"id":"cancellation","title":"취소 규정","preview":"투어 시작 24시간 전까지 무료 취소 가능합니다.","content":["투어 시작 24시간 전까지 무료 취소 가능합니다.","당일 취소 및 노쇼(no-show)는 환불되지 않습니다."]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'ko'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"픽업 및 드롭오프","content":["픽업 장소는 두 곳입니다: 홍대입구역 8번 출구(08:00), 명동역 2번 출구(08:30).","출발 시각 10분 전까지 미팅 포인트에 도착해 주시기 바랍니다.","가이드가 버스와 함께 역 출구에서 기다립니다.","드롭오프는 역순입니다. 명동 18:00쯤, 홍대입구역 18:30쯤.","귀경 시각은 대략이며 교통 상황에 따라 달라집니다.","고정 노선 그룹 투어이며, 미팅 포인트까지는 여행자가 직접 오셔야 합니다."],"preview":"픽업 장소는 두 곳입니다: 홍대입구역 8번 출구(08:00), 명동역 2번 출구(08:30)."},{"id":"walking","title":"도보와 지형","content":["전체적으로 보통 수준 — 하루 약 5–6 km이며 짧게 힘든 구간이 섞여 있습니다.","산정호수: 평탄한 3.2 km 순환 코스, 오르막 없음, 60–90분.","재인폭포: 80 m 출렁다리는 평지지만 흔들립니다. 소 쪽으로 내려가는 데크길은 오르내림 모두 계단입니다.","포천 아트밸리: 아래에서 능선까지 가파르지만 모노레일이 해결합니다. 힐링 숲길로 내려오는 데 10–15분.","어느 스팟에도 등산이나 정상 등반은 포함되지 않습니다.","발이 편한 앞이 막힌 신발을 권합니다. 협곡 데크길은 젖어 있을 수 있습니다."],"preview":"전체적으로 보통 수준 — 하루 약 5–6 km이며 짧게 힘든 구간이 섞여 있습니다."},{"id":"weather","title":"날씨 정책","content":["봄 (3–5월): 쌀쌀한 아침이면 산정호수 위로 물안개가 피어오르고, 눈 녹은 물이 재인폭포를 힘차게 흐르게 합니다. 해가 길어지면서 천주호의 에메랄드빛도 가장 맑게 보입니다.","여름 (6–8월): 폭포가 가장 힘찬 계절이고, 협곡은 도심보다 몇 도쯤 서늘합니다. 장마철 폭우 때는 재인폭포 데크 구간이 통제될 수 있는데, 이 코스의 유일한 날씨 변수입니다.","가을 (9–11월): 이곳이 가장 좋은 계절입니다. 10월 내내 억새가 명성산 비탈을 은백색으로 물들이고, 호수에는 한 해 중 가장 아름다운 반영이 담기며, 아트밸리의 화강암 절벽은 단풍 한가운데에 놓입니다.","겨울 (12–2월): 한 해 중 가장 한적합니다. 천주호가 얼어붙기도 하고, 호수에서는 눈썰매 축제가 열리며, 폭포도 일부 얼 수 있습니다. 해가 짧아 오후 일정이 조금 빠듯해지고 재인폭포 데크길이 미끄러울 수 있습니다.","가벼운 비: 투어는 대체로 정상 진행; 폭우 시 야외 일정이 단축될 수 있습니다"],"preview":"계절별 변화가 뚜렷하며, 대체 일정이 발생할 수 있습니다"},{"id":"wear","title":"복장 및 준비물","content":["미끄럼 방지 기능이 있는 편안한 워킹화","산악 기온 변화에 대비한 레이어드 의류","가벼운 재킷 또는 바람막이 (서울 도심보다 기온이 낮으며, 특히 산정호수 주변)","여름철 자외선 차단 용품; 겨울철 따뜻한 재킷과 장갑","세 곳 모두 사진 촬영 명소이므로 카메라 또는 휴대폰 준비"],"preview":"워킹화, 레이어드 의류, 계절별 추가 준비물"},{"id":"included","title":"포함 사항","content":["서울 도심 왕복 차량, 자격을 갖춘 영어 가이드, 유류비, 통행료, 주차료.","무료 입장 스팟: 산정호수와 둘레길, 재인폭포, 출렁다리와 스카이워크.","불포함 — 포천 아트밸리 입장료(성인 약 ₩6,000)와 모노레일(성인 왕복 약 ₩5,300), 2026년 기준.","불포함 — 점심(약 ₩15,000–20,000), 음료, 개인 경비, 팁."],"preview":"서울 도심 왕복 차량, 자격을 갖춘 영어 가이드, 유류비, 통행료, 주차료.","variant":"포함"},{"id":"geopark","title":"유네스코 세계지질공원에 대하여","content":["한탄강 유네스코 세계지질공원은 2020년 7월 7일 파리에서 열린 유네스코 제209차 집행이사회에서 인증됐고, 2024년 재인증됐습니다. 경기도 포천과 연천, 강원도 철원에 걸친 한탄강 유역을 아우릅니다.","재인폭포는 지질명소입니다. 현무암 주상절리 위로 떨어지는 약 18 m 폭포이며, 그 아래에서 강이 깎아낸 하식동굴과 포트홀, 가스튜브를 읽을 수 있습니다.","포천 아트밸리는 ''아트밸리와 포천석''이라는 이름으로 등재된 지질명소로, 훗날 한탄강 용암이 그 위로 흘러간 오래된 화강암 기반암입니다.","유네스코 세계지질공원은 지질학적 가치에 대한 지정이며, 유네스코 세계유산 등재와는 다릅니다."],"preview":"오늘 방문하는 스팟 중 두 곳이 지정 지질명소입니다."},{"id":"cancellation","title":"취소 규정","content":["투어 시작 24시간 전까지 무료 취소 가능합니다.","당일 취소 및 노쇼(no-show)는 환불되지 않습니다."],"preview":"투어 시작 24시간 전까지 무료 취소 가능합니다."}]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"staticQuestions"}', '[{"question":"이 투어가 바뀌었나요? 허브아일랜드가 포함이지 않았나요?","answer":"맞습니다. 2026년 8월부터 허브아일랜드 대신 연천의 재인폭포가 들어가고, 제대로 된 현지 점심 스팟이 추가됐습니다. 이유는 재인폭포와 포천 아트밸리가 모두 한탄강 유네스코 세계지질공원의 지질명소이기 때문입니다. 서로 무관한 세 곳을 도는 대신, 하루가 하나로 이어지는 지질 이야기를 들려주게 됐습니다. 허브아일랜드를 꼭 원하신다면 예약 전에 문의해 주세요. 별도 일정으로 진행해 드립니다."},{"question":"이 투어는 무슨 요일에 운행하나요?","answer":"**월요일, 목요일, 토요일에만** 운행합니다. 세 요일 모두 일정이 같으니 여행 계획에 맞는 날로 예약하시면 됩니다. 그 외 요일에는 이 상품을 이용하실 수 없습니다."},{"question":"재인폭포와 아트밸리가 ''유네스코''인 이유는 무엇인가요?","answer":"두 곳 모두 한탄강 유네스코 세계지질공원의 지질명소로 지정돼 있으며, 2020년 7월 7일 인증되고 2024년 재인증됐습니다. 이는 세계지질공원 지정이지 세계유산 등재가 아닙니다. 포천·연천·철원에 걸친 한탄강 유역의 지질학적 가치를 인정한 것입니다. 재인폭포는 현무암 용암과 그 주상절리를, 아트밸리는 그 용암이 흘러간 오래된 화강암 기반암을 보여 줍니다."},{"question":"재인폭포 출렁다리가 무섭나요? 건너지 않아도 되나요?","answer":"길이 80 m, 폭 2 m이고 설계상 발밑에서 실제로 흔들립니다. 대부분의 손님께는 그 점이 매력입니다. 원하지 않으시면 건너지 않으셔도 됩니다. 협곡 위 전망 포인트에서 다리를 건너지 않고도 폭포를 볼 수 있고, 소 쪽으로 내려가는 데크길은 별개의 길입니다. 단단한 땅에 머무르기로 하셔도 아무도 남겨지지 않습니다."},{"question":"입장료가 포함인가요?","answer":"산정호수와 재인폭포는 모두 무료입니다. 포천 아트밸리는 불포함으로, 2026년 기준 입장료 약 ₩6,000에 성인 모노레일 왕복 약 ₩5,300이 더해지며 청소년·군인·어린이는 더 저렴합니다. 점심도 불포함입니다(약 ₩15,000–20,000). 그 밖의 차량, 가이드, 통행료, 주차료는 모두 포함입니다."},{"question":"얼마나 걷나요? 많이 힘든가요?","answer":"하루 총 5–6 km 정도이고, 대부분은 아침의 평탄한 3.2 km 호수 둘레길입니다. 재인폭포는 소 쪽으로 내려가는 데크길에 계단이 있습니다. 아트밸리는 아래에서 능선까지가 가파른데 모노레일이 그 구간을 해결해 줍니다. 올라갈 때는 타고, 내려올 때는 숲길을 걷습니다. 이 투어에 등산이나 정상 등반은 없습니다."},{"question":"점심은 포함인가요? 어떤 선택지가 있나요?","answer":"불포함이며 약 ₩15,000–20,000입니다. 점심은 이동갈비(소갈비)라는 이름의 유래가 된 포천 이동면에서 듭니다. 버섯 요리와 우렁도 이 지역의 대표 특산이고, 이동막걸리는 같은 골짜기에서 빚습니다. 채식 선택지가 필요하시면 가이드에게 말씀해 주세요. 맞는 식당으로 안내해 드립니다."},{"question":"남이섬 당일치기와는 어떻게 다른가요?","answer":"남이섬은 배를 타고 들어가는, 아주 인기 있는 하나의 목적지입니다. 이 코스는 성격이 확연히 다른 세 개의 풍경 — 100년 된 저수지, 현무암 폭포 협곡, 물이 찬 화강암 채석장 — 을 남이섬에 비해 훨씬 한적한 경기 북부에서 만나고, 오후 내내 유네스코 세계지질공원이라는 실이 그 풍경들을 꿰고 있습니다."},{"question":"겨울에도 갈 만한가요?","answer":"네, 다만 장단점이 있습니다. 아트밸리 천주호가 얼어붙은 모습은 이곳 최고의 풍경 중 하나이고, 호수에서는 눈썰매 축제가 열리며, 모든 스팟이 가장 한적합니다. 반면 해가 짧아 오후 일정이 조금 빠듯해지고, 재인폭포 데크길이 얼 수 있습니다. 옷만 제대로 갖춰 입으시면 겨울에도 충분히 좋은 하루입니다."},{"question":"비가 오면 어떻게 되나요?","answer":"투어는 진행됩니다. 호수 둘레길과 아트밸리는 우산 하나면 충분하고, 비는 오히려 재인폭포를 더 힘차게 만듭니다. 유일한 예외는 여름 폭우로, 이때는 안전을 위해 협곡의 데크 구간이 통제될 수 있습니다. 그런 경우에는 취소하지 않고 다른 스팟의 체류 시간을 늘립니다."},{"question":"픽업과 드롭오프는 어디서 하나요?","answer":"서울 두 곳에서 만납니다. 08:00 홍대입구역 8번 출구, 08:30 명동역 2번 출구입니다. 출발 시각 10분 전까지 도착해 주시기 바랍니다 — 가이드가 버스와 함께 출구에서 기다립니다. 드롭오프는 역순으로 명동 18:00쯤, 홍대입구역 18:30쯤이며 교통 상황에 따라 달라집니다."},{"question":"아이나 어르신도 괜찮을까요?","answer":"대부분은 괜찮습니다. 호수 둘레길은 평탄하고, 모노레일이 아트밸리의 오르막을 없애 줍니다. 고려하실 점은 두 가지, 재인폭포 데크길의 계단과 흔들리는 출렁다리입니다. 둘 다 선택 사항이고, 원하지 않으시면 협곡 위 전망 포인트에서 폭포를 보실 수 있습니다. 10시간짜리 하루인 만큼, 자주 쉬어야 하는 분보다는 활동적인 어르신께 더 잘 맞습니다."},{"question":"대중교통으로도 갈 수 있나요?","answer":"쉽지 않습니다. 산정호수, 재인폭포, 아트밸리는 두 개 시군에 걸친 서로 다른 세 지역에 있고, 아트밸리로 가는 버스는 두어 시간에 한 대뿐입니다. 차량 없이 하루에 세 곳을 모두 도는 것은 현실적이지 않습니다. 이 코스가 투어로 존재하는 이유의 대부분이 여기에 있습니다."}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'ko'
  AND detail_payload #> '{"staticQuestions"}' IS NOT DISTINCT FROM '[{"answer":"맞습니다. 2026년 8월부터 허브아일랜드 대신 연천의 재인폭포가 들어가고, 제대로 된 현지 점심 스팟이 추가됐습니다. 이유는 재인폭포와 포천 아트밸리가 모두 한탄강 유네스코 세계지질공원의 지질명소이기 때문입니다. 서로 무관한 세 곳을 도는 대신, 하루가 하나로 이어지는 지질 이야기를 들려주게 됐습니다. 허브아일랜드를 꼭 원하신다면 예약 전에 문의해 주세요. 별도 일정으로 진행해 드립니다.","question":"이 투어가 바뀌었나요? 허브아일랜드가 포함이지 않았나요?"},{"answer":"두 곳 모두 한탄강 유네스코 세계지질공원의 지질명소로 지정돼 있으며, 2020년 7월 7일 인증되고 2024년 재인증됐습니다. 이는 세계지질공원 지정이지 세계유산 등재가 아닙니다. 포천·연천·철원에 걸친 한탄강 유역의 지질학적 가치를 인정한 것입니다. 재인폭포는 현무암 용암과 그 주상절리를, 아트밸리는 그 용암이 흘러간 오래된 화강암 기반암을 보여 줍니다.","question":"재인폭포와 아트밸리가 ''유네스코''인 이유는 무엇인가요?"},{"answer":"길이 80 m, 폭 2 m이고 설계상 발밑에서 실제로 흔들립니다. 대부분의 손님께는 그 점이 매력입니다. 원하지 않으시면 건너지 않으셔도 됩니다. 협곡 위 전망 포인트에서 다리를 건너지 않고도 폭포를 볼 수 있고, 소 쪽으로 내려가는 데크길은 별개의 길입니다. 단단한 땅에 머무르기로 하셔도 아무도 남겨지지 않습니다.","question":"재인폭포 출렁다리가 무섭나요? 건너지 않아도 되나요?"},{"answer":"산정호수와 재인폭포는 모두 무료입니다. 포천 아트밸리는 불포함으로, 2026년 기준 입장료 약 ₩6,000에 성인 모노레일 왕복 약 ₩5,300이 더해지며 청소년·군인·어린이는 더 저렴합니다. 점심도 불포함입니다(약 ₩15,000–20,000). 그 밖의 차량, 가이드, 통행료, 주차료는 모두 포함입니다.","question":"입장료가 포함인가요?"},{"answer":"하루 총 5–6 km 정도이고, 대부분은 아침의 평탄한 3.2 km 호수 둘레길입니다. 재인폭포는 소 쪽으로 내려가는 데크길에 계단이 있습니다. 아트밸리는 아래에서 능선까지가 가파른데 모노레일이 그 구간을 해결해 줍니다. 올라갈 때는 타고, 내려올 때는 숲길을 걷습니다. 이 투어에 등산이나 정상 등반은 없습니다.","question":"얼마나 걷나요? 많이 힘든가요?"},{"answer":"불포함이며 약 ₩15,000–20,000입니다. 점심은 이동갈비(소갈비)라는 이름의 유래가 된 포천 이동면에서 듭니다. 버섯 요리와 우렁도 이 지역의 대표 특산이고, 이동막걸리는 같은 골짜기에서 빚습니다. 채식 선택지가 필요하시면 가이드에게 말씀해 주세요. 맞는 식당으로 안내해 드립니다.","question":"점심은 포함인가요? 어떤 선택지가 있나요?"},{"answer":"남이섬은 배를 타고 들어가는, 아주 인기 있는 하나의 목적지입니다. 이 코스는 성격이 확연히 다른 세 개의 풍경 — 100년 된 저수지, 현무암 폭포 협곡, 물이 찬 화강암 채석장 — 을 남이섬에 비해 훨씬 한적한 경기 북부에서 만나고, 오후 내내 유네스코 세계지질공원이라는 실이 그 풍경들을 꿰고 있습니다.","question":"남이섬 당일치기와는 어떻게 다른가요?"},{"answer":"네, 다만 장단점이 있습니다. 아트밸리 천주호가 얼어붙은 모습은 이곳 최고의 풍경 중 하나이고, 호수에서는 눈썰매 축제가 열리며, 모든 스팟이 가장 한적합니다. 반면 해가 짧아 오후 일정이 조금 빠듯해지고, 재인폭포 데크길이 얼 수 있습니다. 옷만 제대로 갖춰 입으시면 겨울에도 충분히 좋은 하루입니다.","question":"겨울에도 갈 만한가요?"},{"answer":"투어는 진행됩니다. 호수 둘레길과 아트밸리는 우산 하나면 충분하고, 비는 오히려 재인폭포를 더 힘차게 만듭니다. 유일한 예외는 여름 폭우로, 이때는 안전을 위해 협곡의 데크 구간이 통제될 수 있습니다. 그런 경우에는 취소하지 않고 다른 스팟의 체류 시간을 늘립니다.","question":"비가 오면 어떻게 되나요?"},{"answer":"서울 두 곳에서 만납니다. 08:00 홍대입구역 8번 출구, 08:30 명동역 2번 출구입니다. 출발 시각 10분 전까지 도착해 주시기 바랍니다 — 가이드가 버스와 함께 출구에서 기다립니다. 드롭오프는 역순으로 명동 18:00쯤, 홍대입구역 18:30쯤이며 교통 상황에 따라 달라집니다.","question":"픽업과 드롭오프는 어디서 하나요?"},{"answer":"대부분은 괜찮습니다. 호수 둘레길은 평탄하고, 모노레일이 아트밸리의 오르막을 없애 줍니다. 고려하실 점은 두 가지, 재인폭포 데크길의 계단과 흔들리는 출렁다리입니다. 둘 다 선택 사항이고, 원하지 않으시면 협곡 위 전망 포인트에서 폭포를 보실 수 있습니다. 10시간짜리 하루인 만큼, 자주 쉬어야 하는 분보다는 활동적인 어르신께 더 잘 맞습니다.","question":"아이나 어르신도 괜찮을까요?"},{"answer":"쉽지 않습니다. 산정호수, 재인폭포, 아트밸리는 두 개 시군에 걸친 서로 다른 세 지역에 있고, 아트밸리로 가는 버스는 두어 시간에 한 대뿐입니다. 차량 없이 하루에 세 곳을 모두 도는 것은 현실적이지 않습니다. 이 코스가 투어로 존재하는 이유의 대부분이 여기에 있습니다.","question":"대중교통으로도 갈 수 있나요?"}]'::jsonb;

