  detail_payload = jsonb_set(detail_payload, '{"whyTourWorks","lessIdealFor"}', '["想要以購物為主或高強度活動的旅客","需要一份完全室內的雨天備案的人","非看知名單一地標不可的旅客（建議改選水原華城）","每一站都需要無台階通行的團體","無法在週一、週四或週六出遊的旅客（僅這三天發團）"]'::jsonb, true),
