WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'zh-TW'
  AND detail_payload #> '{"whyTourWorks","lessIdealFor"}' IS NOT DISTINCT FROM '["想要以購物為主或高強度活動的旅客","需要一份完全室內的雨天備案的人","非看知名單一地標不可的旅客（建議改選水原華城）","每一站都需要無台階通行的團體"]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"出發日","preview":"本行程**僅於週一、週四、週六出發**，請選擇其中一天預訂。","content":["本行程**僅於週一、週四、週六出發**，請選擇其中一天預訂。","三個出發日的路線、時間與兩個上車地點完全相同。","若您的行程中沒有週一、週四或週六，本產品無法改至其他日期——這是固定發團的小團行程，並非私人包車。"]},{"id":"pickup","title":"接送服務","preview":"兩個接客地點：弘大入口站8號出口（08:00）與明洞站2號出口（08:30）。","content":["兩個接客地點：弘大入口站8號出口（08:00）與明洞站2號出口（08:30）。","請於出發時間前 10 分鐘抵達您的集合點。","導遊會帶著遊覽車在車站出口等候。","送返順序相反：約 18:00 明洞，約 18:30 弘大入口站。","回程時間為約略值，視交通狀況而定。","本行程為固定路線的團體形式；旅客請自行前往集合點。"]},{"id":"walking","title":"步行與地形","preview":"整體中等——全天約 5–6 公里，其中夾雜幾段較費力的短程。","content":["整體中等——全天約 5–6 公里，其中夾雜幾段較費力的短程。","山井湖：平坦的 3.2 公里環湖步道，沒有上坡，60–90 分鐘。","載仁瀑布：80 公尺的吊橋是平的但會晃；往瀑潭下行的木棧道去回都有階梯。","抱川藝術谷：從山下到坑緣坡度陡——由單軌電車解決；沿療癒森林步道走下來約 10–15 分鐘。","任何一站都不包含登山健行或攻頂。","建議穿著舒適的包鞋；峽谷的木棧道可能濕滑。"]},{"id":"weather","title":"天氣政策","preview":"季節差異顯著；替換行程十分普遍","content":["春季（3–5 月）: 涼爽的清晨，山井湖面會升起薄霧，融雪也讓載仁瀑布水勢強勁。隨著日照拉長，天柱湖呈現最清澈的翡翠色。","夏季（6–8 月）: 瀑布水勢最為磅礡，峽谷裡也比城市涼上好幾度。梅雨季的豪雨可能導致載仁瀑布的平台路段封閉——這是本路線唯一的天候風險。","秋季（9–11 月）: 這裡最強的季節。整個十月，芒草把鳴聲山的山坡染成銀白，湖面呈現全年最美的倒影，藝術谷的花崗岩壁則被滿山秋色環繞。","冬季（12–2 月）: 全年人潮最少的時候。天柱湖可能整片結冰，湖區會舉辦雪橇慶典，瀑布也可能部分結冰。白晝短，下午節奏較緊湊，載仁的木棧道也可能濕滑。","小雨：行程通常照常進行；大雨可能縮短戶外停留時間"]},{"id":"wear","title":"穿著與攜帶建議","preview":"步行鞋、保暖衣物及季節性裝備","content":["具防滑功能的舒適步行鞋","適應山區溫差的多層次穿搭","輕便夾克或防風外套（氣溫較首爾市中心低，尤其是山井湖一帶）","夏季注意防曬；冬季備妥保暖外套與手套","相機或手機，三個景點均有絕佳拍照機會"]},{"id":"included","title":"費用包含","preview":"首爾市中心往返交通、持照英語導遊、燃料費、過路費與停車費。","variant":"包含","content":["首爾市中心往返交通、持照英語導遊、燃料費、過路費與停車費。","免費入場的站點：山井湖與環湖步道、載仁瀑布、吊橋與天空步道。","費用未含——抱川藝術谷入場費（成人約 ₩6,000）與單軌電車（成人來回約 ₩5,300），2026 年票價。","費用未含——午餐（約 ₩15,000–20,000）、飲料、個人消費與小費。"]},{"id":"geopark","title":"關於聯合國教科文組織世界地質公園","preview":"今天有兩站是指定的地質景點。","content":["漢灘江聯合國教科文組織世界地質公園於 2020 年 7 月 7 日，由聯合國教科文組織在巴黎召開的第 209 屆執行委員會認證，並於 2024 年再認證。範圍涵蓋京畿道抱川與漣川、以及江原道鐵原一帶的漢灘江流域。","載仁瀑布是地質景點：一道約 18 公尺高、落在玄武岩柱狀節理上的瀑布，底部還能讀出河蝕洞穴、甌穴與氣孔管。","抱川藝術谷是以「藝術谷與抱川石」之名列入的地質景點：那是後來漢灘江熔岩流過的古老花崗岩基盤。","聯合國教科文組織世界地質公園是一項地質學認證——與聯合國教科文組織的世界遺產登錄並不相同。"]},{"id":"cancellation","title":"取消政策","preview":"行程開始前24小時以上可免費取消。","content":["行程開始前24小時以上可免費取消。","當日取消及未出席者恕不退款。"]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'zh-TW'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"接送服務","content":["兩個接客地點：弘大入口站8號出口（08:00）與明洞站2號出口（08:30）。","請於出發時間前 10 分鐘抵達您的集合點。","導遊會帶著遊覽車在車站出口等候。","送返順序相反：約 18:00 明洞，約 18:30 弘大入口站。","回程時間為約略值，視交通狀況而定。","本行程為固定路線的團體形式；旅客請自行前往集合點。"],"preview":"兩個接客地點：弘大入口站8號出口（08:00）與明洞站2號出口（08:30）。"},{"id":"walking","title":"步行與地形","content":["整體中等——全天約 5–6 公里，其中夾雜幾段較費力的短程。","山井湖：平坦的 3.2 公里環湖步道，沒有上坡，60–90 分鐘。","載仁瀑布：80 公尺的吊橋是平的但會晃；往瀑潭下行的木棧道去回都有階梯。","抱川藝術谷：從山下到坑緣坡度陡——由單軌電車解決；沿療癒森林步道走下來約 10–15 分鐘。","任何一站都不包含登山健行或攻頂。","建議穿著舒適的包鞋；峽谷的木棧道可能濕滑。"],"preview":"整體中等——全天約 5–6 公里，其中夾雜幾段較費力的短程。"},{"id":"weather","title":"天氣政策","content":["春季（3–5 月）: 涼爽的清晨，山井湖面會升起薄霧，融雪也讓載仁瀑布水勢強勁。隨著日照拉長，天柱湖呈現最清澈的翡翠色。","夏季（6–8 月）: 瀑布水勢最為磅礡，峽谷裡也比城市涼上好幾度。梅雨季的豪雨可能導致載仁瀑布的平台路段封閉——這是本路線唯一的天候風險。","秋季（9–11 月）: 這裡最強的季節。整個十月，芒草把鳴聲山的山坡染成銀白，湖面呈現全年最美的倒影，藝術谷的花崗岩壁則被滿山秋色環繞。","冬季（12–2 月）: 全年人潮最少的時候。天柱湖可能整片結冰，湖區會舉辦雪橇慶典，瀑布也可能部分結冰。白晝短，下午節奏較緊湊，載仁的木棧道也可能濕滑。","小雨：行程通常照常進行；大雨可能縮短戶外停留時間"],"preview":"季節差異顯著；替換行程十分普遍"},{"id":"wear","title":"穿著與攜帶建議","content":["具防滑功能的舒適步行鞋","適應山區溫差的多層次穿搭","輕便夾克或防風外套（氣溫較首爾市中心低，尤其是山井湖一帶）","夏季注意防曬；冬季備妥保暖外套與手套","相機或手機，三個景點均有絕佳拍照機會"],"preview":"步行鞋、保暖衣物及季節性裝備"},{"id":"included","title":"費用包含","content":["首爾市中心往返交通、持照英語導遊、燃料費、過路費與停車費。","免費入場的站點：山井湖與環湖步道、載仁瀑布、吊橋與天空步道。","費用未含——抱川藝術谷入場費（成人約 ₩6,000）與單軌電車（成人來回約 ₩5,300），2026 年票價。","費用未含——午餐（約 ₩15,000–20,000）、飲料、個人消費與小費。"],"preview":"首爾市中心往返交通、持照英語導遊、燃料費、過路費與停車費。","variant":"包含"},{"id":"geopark","title":"關於聯合國教科文組織世界地質公園","content":["漢灘江聯合國教科文組織世界地質公園於 2020 年 7 月 7 日，由聯合國教科文組織在巴黎召開的第 209 屆執行委員會認證，並於 2024 年再認證。範圍涵蓋京畿道抱川與漣川、以及江原道鐵原一帶的漢灘江流域。","載仁瀑布是地質景點：一道約 18 公尺高、落在玄武岩柱狀節理上的瀑布，底部還能讀出河蝕洞穴、甌穴與氣孔管。","抱川藝術谷是以「藝術谷與抱川石」之名列入的地質景點：那是後來漢灘江熔岩流過的古老花崗岩基盤。","聯合國教科文組織世界地質公園是一項地質學認證——與聯合國教科文組織的世界遺產登錄並不相同。"],"preview":"今天有兩站是指定的地質景點。"},{"id":"cancellation","title":"取消政策","content":["行程開始前24小時以上可免費取消。","當日取消及未出席者恕不退款。"],"preview":"行程開始前24小時以上可免費取消。"}]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"staticQuestions"}', '[{"question":"這個行程改了什麼——原本不是有香草島樂園嗎？","answer":"原本確實有。自 2026 年 8 月起，路線把香草島樂園換成漣川的載仁瀑布，並加入一站道地的在地午餐。原因是載仁瀑布與抱川藝術谷同為漢灘江聯合國教科文組織世界地質公園的地質景點，因此這一天現在說的是一個彼此相連的地質故事，而不是三個互不相干的景點。如果你特別想去香草島樂園，請在預訂前與我們聯繫——我們可以另行安排。"},{"question":"本行程每週哪幾天出發？","answer":"**僅於週一、週四與週六出發**。三天的行程內容完全相同，請選擇方便的一天預訂。其他日期不提供本產品。"},{"question":"載仁瀑布與藝術谷的「聯合國教科文組織」身分是什麼？","answer":"兩者都是漢灘江聯合國教科文組織世界地質公園的指定地質景點，該地質公園於 2020 年 7 月 7 日獲得認證，並於 2024 年再認證。這是世界地質公園的認證，而不是世界遺產登錄——它表彰的是橫跨抱川、漣川與鐵原的漢灘江流域地質。載仁瀑布展現的是玄武岩熔岩與它的柱狀節理；藝術谷展現的則是熔岩當年流過的古老花崗岩基盤。"},{"question":"載仁瀑布的吊橋會不會很可怕？可以不走嗎？","answer":"它長 80 公尺、寬 2 公尺，腳下確實會晃，而這正是多數客人覺得有趣的地方。你也完全可以略過：峽谷邊緣的觀景點不用過橋就看得到瀑布，通往瀑潭的木棧道則是另一條路線。若你寧可待在踏實的地面上，不會有人被丟下。"},{"question":"門票有含嗎？","answer":"山井湖與載仁瀑布都免費。抱川藝術谷未含在費用內——2026 年入場費約 ₩6,000，成人單軌電車來回約再加 ₩5,300，青少年、軍人與兒童票價較低。午餐同樣未含（約 ₩15,000–20,000）。其餘一切——交通、導遊、過路費與停車費——都已包含。"},{"question":"全程要走多少路？難度如何？","answer":"一整天大約 5–6 公里，其中大部分是上午平坦的 3.2 公里環湖步道。載仁瀑布往瀑潭下行的木棧道有階梯。藝術谷從山下到坑緣坡度陡，但單軌電車解決了這一段——搭上去，再穿過森林走下來。本行程不包含登山健行，也沒有攻頂路段。"},{"question":"午餐有含嗎？有哪些選擇？","answer":"未含，約 ₩15,000–20,000。午餐地點在梨洞，也就是梨洞排骨（牛小排）名稱的由來，屬抱川的一個面。香菇料理與田螺（우렁）是另外兩樣在地名產，梨洞馬格利酒也在同一條溪谷裡釀造。如果你需要素食選擇，請告訴導遊，他們會帶你到合適的餐桌。"},{"question":"這和南怡島一日遊有什麼不同？","answer":"南怡島是一個要搭渡輪前往、極受歡迎的單一目的地。這條路線則是三種截然不同的地景——一座百年水庫、一道玄武岩瀑布峽谷，以及一座積水的花崗岩採石場——而且位在京畿道人潮遠不及南怡島的一帶，整個下午還有一條聯合國教科文組織世界地質公園的主線貫穿其中。"},{"question":"冬天來值得嗎？","answer":"值得，但有取捨。藝術谷的天柱湖結冰是這裡最好看的景象之一，湖區會舉辦雪橇慶典，每一站也都處於全年最安靜的狀態。相對地：白晝短，下午的節奏會比較緊湊，載仁瀑布的木棧道也可能結冰。只要穿得夠保暖，這會是一個很有分量的冬日行程。"},{"question":"下雨的話會怎樣？","answer":"行程照常出發。環湖步道與藝術谷撐把傘就沒問題，雨勢其實還會讓載仁瀑布更有氣勢。唯一真正的例外是夏季豪雨，此時峽谷的平台路段可能為安全起見封閉——遇到這種情況，我們會延長其他站的時間，而不是取消當天行程。"},{"question":"在哪裡接送？","answer":"首爾兩個集合點：08:00 弘大入口站8號出口、08:30 明洞站2號出口。請於各自出發時間前 10 分鐘抵達——導遊會帶著遊覽車在出口等候。回程順序相反：約 18:00 明洞，約 18:30 弘大入口站，實際時間視交通狀況而定。"},{"question":"適合小孩或年長者嗎？","answer":"對大多數人來說是適合的。環湖步道平坦，單軌電車也免去了藝術谷的爬坡。需要斟酌的只有兩件事：載仁瀑布木棧道的階梯，以及會搖晃的吊橋——兩者都是自由選擇，不想走的人也能在峽谷邊緣的觀景點看到瀑布。這是一趟 10 小時的行程，因此比較適合體力好的年長旅客，而非需要頻繁休息的人。"},{"question":"可以改搭大眾運輸自己去嗎？","answer":"會相當困難。山井湖、載仁瀑布與藝術谷分屬兩個郡的三個不同區域，而往藝術谷的公車每隔數小時才有一班。沒有車輛要在一天內走完這三處並不實際——這也正是這條路線之所以以團體行程存在的主要原因。"}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'zh-TW'
