UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"catalog_card","badges"}', '["Excursión de un día desde Seúl","Lun · jue · sáb","Geoparque UNESCO","Cascada","Paseo junto al lago","Grupo reducido"]'::jsonb, true),
