UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"catalog_card","shortCardDescription"}', '"Una excursión de un día desde Seúl más sosegada y construida sobre geología real. Recorra el circuito llano de 3,2 km alrededor del lago Sanjeong, bajo el monte Myeongseongsan; pruebe el Idong galbi (costillas de ternera), el plato propio de Pocheon; cruce después un puente colgante de 80 m para quedar frente a la cascada de Jaein mientras cae 18 m por columnas de basalto, y termine dentro de la cantera de granito de Pocheon Art Valley (el valle del arte de Pocheon), donde el agua de manantial ha llenado el hueco hasta formar el esmeralda lago Cheonjuho. La cascada de Jaein y Art Valley son geositios del Geoparque Mundial de la UNESCO del Hantangang: el mismo paisaje visto desde sus dos mitades opuestas. Sale lunes, jueves y sábados."'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'es'
  AND detail_payload #>> '{"catalog_card","shortCardDescription"}' IS NOT DISTINCT FROM 'Una excursión de un día desde Seúl más sosegada y construida sobre geología real. Recorra el circuito llano de 3,2 km alrededor del lago Sanjeong, bajo el monte Myeongseongsan; pruebe el Idong galbi (costillas de ternera), el plato propio de Pocheon; cruce después un puente colgante de 80 m para quedar frente a la cascada de Jaein mientras cae 18 m por columnas de basalto, y termine dentro de la cantera de granito de Pocheon Art Valley (el valle del arte de Pocheon), donde el agua de manantial ha llenado el hueco hasta formar el esmeralda lago Cheonjuho. La cascada de Jaein y Art Valley son geositios del Geoparque Mundial de la UNESCO del Hantangang: el mismo paisaje visto desde sus dos mitades opuestas.';

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"whyTourWorks","lessIdealFor"}', '["Viajeros que quieran un día de compras o de mucha actividad","Quien necesite un plan totalmente cubierto para un día de lluvia","Visitantes decididos a ver un gran monumento único (mejor la fortaleza Hwaseong de Suwon)","Grupos que necesiten acceso sin escalones en todas las paradas","Viajeros que no pueden viajar un lunes, jueves o sábado (los únicos días de salida)"]'::jsonb, true),
