WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'es'
  AND detail_payload #> '{"whyTourWorks","lessIdealFor"}' IS NOT DISTINCT FROM '["Viajeros que quieran un día de compras o de mucha actividad","Quien necesite un plan totalmente cubierto para un día de lluvia","Visitantes decididos a ver un gran monumento único (mejor la fortaleza Hwaseong de Suwon)","Grupos que necesiten acceso sin escalones en todas las paradas"]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"Días de salida","preview":"Este tour sale **únicamente los lunes, jueves y sábados**: reserva una de esas fechas.","content":["Este tour sale **únicamente los lunes, jueves y sábados**: reserva una de esas fechas.","La ruta, los horarios y los dos puntos de recogida son idénticos en los tres días de salida.","Si tus fechas no incluyen un lunes, jueves o sábado, el tour no puede trasladarse a otro día: es una salida de grupo reducido con horario fijo, no un vehículo privado."]},{"id":"pickup","title":"Recogida y regreso","preview":"Dos puntos de recogida: la estación de la Universidad Hongik (salida 8, 08:00) y la estación de Myeongdong (salida 2, 08:30).","content":["Dos puntos de recogida: la estación de la Universidad Hongik (salida 8, 08:00) y la estación de Myeongdong (salida 2, 08:30).","Le rogamos llegar a su punto de encuentro 10 minutos antes de la hora de salida.","Su guía espera con el autobús en la salida de la estación.","El regreso invierte el orden: Myeongdong hacia las 18:00 y la estación de la Universidad Hongik hacia las 18:30.","Las horas de regreso son aproximadas y dependen del tráfico.","Se trata de un formato de grupo con ruta fija; los viajeros llegan por su cuenta al punto de encuentro."]},{"id":"walking","title":"Caminata y terreno","preview":"Moderada en conjunto: entre 5 y 6 km a lo largo del día, con algunos tramos exigentes y breves.","content":["Moderada en conjunto: entre 5 y 6 km a lo largo del día, con algunos tramos exigentes y breves.","Lago Sanjeong: circuito llano de 3,2 km, sin cuestas, 60–90 min.","Cascada de Jaein: el puente colgante de 80 m es llano pero se balancea; la pasarela que baja hacia la poza tiene escaleras en ambos sentidos.","Pocheon Art Valley: pendiente pronunciada de la base al borde superior, que el monorraíl resuelve; la bajada a pie por el Bosque Sanador es de 10–15 min.","No se incluye senderismo ni ascensión a ninguna cima en ninguna parada.","Se recomienda calzado cerrado y cómodo; la pasarela del desfiladero puede estar mojada."]},{"id":"weather","title":"Política meteorológica","preview":"Gran variedad estacional; los cambios de itinerario son frecuentes","content":["Primavera (mar.–may.): La niebla se levanta del lago Sanjeong en las mañanas frescas, y el deshielo mantiene la cascada de Jaein con mucho caudal. El Cheonjuho luce su esmeralda más nítido a medida que se alargan los días.","Verano (jun.–ago.): La cascada alcanza su máxima potencia y el desfiladero se mantiene varios grados más fresco que la ciudad. Las lluvias intensas del monzón pueden cerrar los tramos de pasarela de la cascada de Jaein: el único riesgo meteorológico de esta ruta.","Otoño (sept.–nov.): La mejor estación aquí. La hierba plateada tiñe de blanco plateado las laderas del monte Myeongseongsan durante todo octubre, el lago ofrece los mejores reflejos del año y las paredes de granito de Art Valley quedan enmarcadas por el follaje en pleno color.","Invierno (dic.–feb.): La menor afluencia del año. El Cheonjuho puede helarse por completo, el lago acoge su festival de trineos y la cascada puede congelarse parcialmente. Los días son cortos, así que la tarde va más justa y la pasarela de Jaein puede resbalar.","Lluvia ligera: el tour generalmente continúa; la lluvia intensa puede acortar las paradas al aire libre"]},{"id":"wear","title":"Qué ponerse y qué traer","preview":"Calzado para caminar, ropa en capas y accesorios según la temporada","content":["Zapatos cómodos para caminar con buena adherencia","Ropa en capas para adaptarse a los cambios de temperatura en la montaña","Chaqueta ligera o cortavientos (hace más frío que en el centro de Seúl, especialmente en el lago Sanjeong)","Protección solar en verano; chaqueta abrigada y guantes en invierno","Cámara o teléfono para aprovechar las excelentes oportunidades fotográficas en las tres paradas"]},{"id":"included","title":"Qué incluye","preview":"Transporte de ida y vuelta desde el centro de Seúl, guía titulado en inglés, combustible, peajes y aparcamiento.","variant":"incluido","content":["Transporte de ida y vuelta desde el centro de Seúl, guía titulado en inglés, combustible, peajes y aparcamiento.","Paradas de entrada gratuita: el lago Sanjeong y su sendero circular, la cascada de Jaein, el puente colgante y el skywalk.","No incluido: la entrada a Pocheon Art Valley (≈ ₩6.000 adultos) y el monorraíl (≈ ₩5.300 por adulto, ida y vuelta), tarifas de 2026.","No incluido: el almuerzo (≈ ₩15.000–20.000), las bebidas, los gastos personales y las propinas."]},{"id":"geopark","title":"Sobre el Geoparque Mundial de la UNESCO","preview":"Dos de las paradas de hoy son geositios designados.","content":["El Geoparque Mundial de la UNESCO del Hantangang fue certificado el 7 de julio de 2020 por el 209.º Consejo Ejecutivo de la UNESCO en París, y revalidado en 2024. Abarca la cuenca del río Hantangang a su paso por Pocheon y Yeoncheon, en Gyeonggi-do, y Cheorwon, en Gangwon-do.","La cascada de Jaein es un geositio: una cascada de ≈18 m sobre disyunción columnar basáltica, con una cueva excavada por el río, marmitas de gigante y tubos de gas legibles en su base.","Pocheon Art Valley es un geositio inscrito como «Art Valley y la piedra de Pocheon»: la antigua roca de granito del basamento sobre la que después fluyó la lava del Hantangang.","Un Geoparque Mundial de la UNESCO es una designación geológica: no es lo mismo que una inscripción en el Patrimonio Mundial de la UNESCO."]},{"id":"cancellation","title":"Cancelación","preview":"Cancelación gratuita hasta 24 horas antes del inicio del tour.","content":["Cancelación gratuita hasta 24 horas antes del inicio del tour.","Las cancelaciones el mismo día y las no presentaciones no son reembolsables."]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'es'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"Recogida y regreso","content":["Dos puntos de recogida: la estación de la Universidad Hongik (salida 8, 08:00) y la estación de Myeongdong (salida 2, 08:30).","Le rogamos llegar a su punto de encuentro 10 minutos antes de la hora de salida.","Su guía espera con el autobús en la salida de la estación.","El regreso invierte el orden: Myeongdong hacia las 18:00 y la estación de la Universidad Hongik hacia las 18:30.","Las horas de regreso son aproximadas y dependen del tráfico.","Se trata de un formato de grupo con ruta fija; los viajeros llegan por su cuenta al punto de encuentro."],"preview":"Dos puntos de recogida: la estación de la Universidad Hongik (salida 8, 08:00) y la estación de Myeongdong (salida 2, 08:30)."},{"id":"walking","title":"Caminata y terreno","content":["Moderada en conjunto: entre 5 y 6 km a lo largo del día, con algunos tramos exigentes y breves.","Lago Sanjeong: circuito llano de 3,2 km, sin cuestas, 60–90 min.","Cascada de Jaein: el puente colgante de 80 m es llano pero se balancea; la pasarela que baja hacia la poza tiene escaleras en ambos sentidos.","Pocheon Art Valley: pendiente pronunciada de la base al borde superior, que el monorraíl resuelve; la bajada a pie por el Bosque Sanador es de 10–15 min.","No se incluye senderismo ni ascensión a ninguna cima en ninguna parada.","Se recomienda calzado cerrado y cómodo; la pasarela del desfiladero puede estar mojada."],"preview":"Moderada en conjunto: entre 5 y 6 km a lo largo del día, con algunos tramos exigentes y breves."},{"id":"weather","title":"Política meteorológica","content":["Primavera (mar.–may.): La niebla se levanta del lago Sanjeong en las mañanas frescas, y el deshielo mantiene la cascada de Jaein con mucho caudal. El Cheonjuho luce su esmeralda más nítido a medida que se alargan los días.","Verano (jun.–ago.): La cascada alcanza su máxima potencia y el desfiladero se mantiene varios grados más fresco que la ciudad. Las lluvias intensas del monzón pueden cerrar los tramos de pasarela de la cascada de Jaein: el único riesgo meteorológico de esta ruta.","Otoño (sept.–nov.): La mejor estación aquí. La hierba plateada tiñe de blanco plateado las laderas del monte Myeongseongsan durante todo octubre, el lago ofrece los mejores reflejos del año y las paredes de granito de Art Valley quedan enmarcadas por el follaje en pleno color.","Invierno (dic.–feb.): La menor afluencia del año. El Cheonjuho puede helarse por completo, el lago acoge su festival de trineos y la cascada puede congelarse parcialmente. Los días son cortos, así que la tarde va más justa y la pasarela de Jaein puede resbalar.","Lluvia ligera: el tour generalmente continúa; la lluvia intensa puede acortar las paradas al aire libre"],"preview":"Gran variedad estacional; los cambios de itinerario son frecuentes"},{"id":"wear","title":"Qué ponerse y qué traer","content":["Zapatos cómodos para caminar con buena adherencia","Ropa en capas para adaptarse a los cambios de temperatura en la montaña","Chaqueta ligera o cortavientos (hace más frío que en el centro de Seúl, especialmente en el lago Sanjeong)","Protección solar en verano; chaqueta abrigada y guantes en invierno","Cámara o teléfono para aprovechar las excelentes oportunidades fotográficas en las tres paradas"],"preview":"Calzado para caminar, ropa en capas y accesorios según la temporada"},{"id":"included","title":"Qué incluye","content":["Transporte de ida y vuelta desde el centro de Seúl, guía titulado en inglés, combustible, peajes y aparcamiento.","Paradas de entrada gratuita: el lago Sanjeong y su sendero circular, la cascada de Jaein, el puente colgante y el skywalk.","No incluido: la entrada a Pocheon Art Valley (≈ ₩6.000 adultos) y el monorraíl (≈ ₩5.300 por adulto, ida y vuelta), tarifas de 2026.","No incluido: el almuerzo (≈ ₩15.000–20.000), las bebidas, los gastos personales y las propinas."],"preview":"Transporte de ida y vuelta desde el centro de Seúl, guía titulado en inglés, combustible, peajes y aparcamiento.","variant":"incluido"},{"id":"geopark","title":"Sobre el Geoparque Mundial de la UNESCO","content":["El Geoparque Mundial de la UNESCO del Hantangang fue certificado el 7 de julio de 2020 por el 209.º Consejo Ejecutivo de la UNESCO en París, y revalidado en 2024. Abarca la cuenca del río Hantangang a su paso por Pocheon y Yeoncheon, en Gyeonggi-do, y Cheorwon, en Gangwon-do.","La cascada de Jaein es un geositio: una cascada de ≈18 m sobre disyunción columnar basáltica, con una cueva excavada por el río, marmitas de gigante y tubos de gas legibles en su base.","Pocheon Art Valley es un geositio inscrito como «Art Valley y la piedra de Pocheon»: la antigua roca de granito del basamento sobre la que después fluyó la lava del Hantangang.","Un Geoparque Mundial de la UNESCO es una designación geológica: no es lo mismo que una inscripción en el Patrimonio Mundial de la UNESCO."],"preview":"Dos de las paradas de hoy son geositios designados."},{"id":"cancellation","title":"Cancelación","content":["Cancelación gratuita hasta 24 horas antes del inicio del tour.","Las cancelaciones el mismo día y las no presentaciones no son reembolsables."],"preview":"Cancelación gratuita hasta 24 horas antes del inicio del tour."}]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"staticQuestions"}', '[{"question":"¿Qué ha cambiado en esta excursión? ¿No incluía Herb Island?","answer":"Así era. Desde agosto de 2026 la ruta cambia Herb Island por la cascada de Jaein, en Yeoncheon, y añade una parada para comer en un local de la zona. El motivo es que la cascada de Jaein y Pocheon Art Valley son ambas geositios del Geoparque Mundial de la UNESCO del Hantangang, de manera que el día cuenta ahora una única historia geológica encadenada en lugar de tres paradas inconexas. Si desea concretamente Herb Island, contacte con nosotros antes de reservar: lo organizamos como un servicio aparte."},{"question":"¿Qué días de la semana opera este tour?","answer":"Opera **solo los lunes, jueves y sábados**. El itinerario es el mismo los tres días, así que reserva el que mejor encaje en tu viaje. El resto de días no están disponibles en este producto."},{"question":"¿Qué hace que la cascada de Jaein y Art Valley sean «UNESCO»?","answer":"Ambas están designadas geositios del Geoparque Mundial de la UNESCO del Hantangang, certificado el 7 de julio de 2020 y revalidado en 2024. Se trata de una designación de geoparque, no de una inscripción en el Patrimonio Mundial: reconoce la geología de la cuenca del río Hantangang a su paso por Pocheon, Yeoncheon y Cheorwon. La cascada de Jaein muestra la lava basáltica y su disyunción columnar; Art Valley muestra el antiguo basamento de granito sobre el que fluyó esa lava."},{"question":"¿Da miedo el puente colgante de la cascada de Jaein? ¿Puedo saltármelo?","answer":"Mide 80 m de largo y 2 m de ancho, y sí se balancea bajo los pies por diseño; para la mayoría de los clientes ese es justamente su atractivo. Puede omitirlo por completo: el mirador del borde permite ver la cascada sin cruzar, y la pasarela hacia la poza es un camino independiente. Nadie se queda atrás si prefiere permanecer en tierra firme."},{"question":"¿Están incluidas las entradas?","answer":"El lago Sanjeong y la cascada de Jaein son ambos gratuitos. Pocheon Art Valley no está incluido: unos ₩6.000 de entrada más unos ₩5.300 por el trayecto de ida y vuelta en monorraíl para un adulto en 2026, con tarifas más bajas para jóvenes, militares y niños. El almuerzo tampoco está incluido (≈ ₩15.000–20.000). Todo lo demás — transporte, guía, peajes y aparcamiento — está cubierto."},{"question":"¿Cuánto se camina y qué dificultad tiene?","answer":"Entre 5 y 6 km a lo largo del día, la mayor parte en el circuito llano de 3,2 km del lago por la mañana. La cascada de Jaein tiene escaleras en la pasarela que baja hacia la poza. Art Valley presenta una pendiente pronunciada de la base al borde superior, que el monorraíl resuelve: se sube en él y se baja a pie por el bosque. En esta excursión no hay senderismo ni ascensión a ninguna cima."},{"question":"¿Está incluido el almuerzo y qué opciones hay?","answer":"No está incluido; unos ₩15.000–20.000. El almuerzo es en Idong, el distrito de Pocheon que da nombre al Idong galbi (costillas de ternera). Los platos de setas y el uleong (caracol de agua dulce) son las otras especialidades locales, y el makgeolli de Idong se elabora en este mismo valle. Comunique a su guía si necesita opciones vegetarianas y le indicará la mesa adecuada."},{"question":"¿En qué se diferencia de una excursión a la isla de Nami?","answer":"La isla de Nami es un único destino, muy popular, al que se llega en ferry. Esta ruta reúne tres paisajes verdaderamente distintos — un embalse centenario, un desfiladero con una cascada de basalto y una cantera de granito inundada — en una parte de Gyeonggi que recibe una fracción del gentío de Nami, con el hilo conductor de un Geoparque Mundial de la UNESCO recorriendo toda la tarde."},{"question":"¿Merece la pena en invierno?","answer":"Sí, con sus contrapartidas. El Cheonjuho helado en Art Valley es una de las mejores estampas del lugar, el lago acoge un festival de trineos y todas las paradas están en su momento más tranquilo. En contra: los días son cortos, por lo que la tarde va más justa, y la pasarela de la cascada de Jaein puede tener hielo. Bien abrigado, es un gran día de invierno."},{"question":"¿Qué pasa si llueve?","answer":"La excursión se realiza igualmente. El circuito del lago y Art Valley se disfrutan bien con paraguas, y la lluvia incluso refuerza la cascada de Jaein. La única excepción real son las lluvias fuertes del verano, cuando los tramos de pasarela del desfiladero pueden cerrarse por seguridad; en ese caso ampliamos las demás paradas en lugar de cancelar el día."},{"question":"¿Dónde son la recogida y el regreso?","answer":"Dos puntos de encuentro en Seúl: la estación de la Universidad Hongik (salida 8) a las 08:00 y la estación de Myeongdong (salida 2) a las 08:30. Le rogamos llegar 10 minutos antes de su hora de salida: el guía espera en la salida con el autobús. El regreso invierte el orden: Myeongdong hacia las 18:00 y la estación de la Universidad Hongik hacia las 18:30, según el tráfico."},{"question":"¿Es adecuada para niños o personas mayores?","answer":"Para la mayoría, sí. El circuito del lago es llano y el monorraíl elimina la subida de Art Valley. Los dos puntos a valorar son las escaleras de la pasarela de la cascada de Jaein y el balanceo del puente colgante: ambos son opcionales, y el mirador del borde ofrece la cascada a quien prefiera no cruzarlo. Es una jornada de 10 horas, así que se adapta mejor a viajeros mayores activos que a quien necesite descansos frecuentes."},{"question":"¿Puedo hacerlo por mi cuenta en transporte público?","answer":"Sería difícil. El lago Sanjeong, la cascada de Jaein y Art Valley se reparten en tres distritos distintos de dos comarcas, y los autobuses a Art Valley pasan solo cada dos horas aproximadamente. Hacer los tres en un día sin vehículo no es realista, y esa es buena parte de la razón por la que esta ruta existe como excursión organizada."}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'es'
