st_herb_museum_fit":1,"mediterranean_herb_garden_fit":1,"quarry_restoration_anchor_fit":1,"emerald_quarry_lake_anchor_fit":1,"seoul_central_hotel_pickup_fit":1,"1925_irrigation_lake_anchor_fit":1,"english_speaking_guide_provided":true,"pocheon_seok_granite_anchor_fit":1,"affordable_format_vs_charter_fit":1,"differentiates_from_dmz_day_trip":true,"year_round_lighting_festival_fit":1,"pocheon_three_pillar_day_trip_fit":1,"china_diaspora_overseas_market_fit":0.95,"legend_of_the_blue_sea_filming_fit":1,"abandoned_quarry_to_culture_park_fit":1,"day_trip_2_3_hour_drive_each_way_fit":1,"korea_drama_filming_density_high_fit":1,"agricultural_reservoir_lake_visit_fit":1,"myeongseongsan_silver_grass_autumn_fit":1,"hosur_concert_hall_quarry_cliff_venue_fit":1,"moon_lovers_scarlet_heart_ryeo_filming_fit":1,"national_tourist_site_1977_designation_fit":1,"sanjeong_lake_sledding_festival_winter_fit":1,"differentiates_from_seoraksan_sokcho_day_trip":true,"korea_first_ecological_restoration_project_fit":1,"chinese_speaking_guide_available_on_advance_notice":true,"differentiates_from_nami_morning_calm_petite_france":true,"japanese_speaking_guide_available_on_advance_notice":true,"blue_house_national_assembly_incheon_airport_granite_source_fit":1}'::jsonb;

