UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"Abfahrtstage","preview":"Diese Tour startet **nur montags, donnerstags und samstags** – bitte buchen Sie eines dieser Daten.","content":["Diese Tour startet **nur montags, donnerstags und samstags** – bitte buchen Sie eines dieser Daten.","Route, Zeiten und beide Abholpunkte sind an allen drei Abfahrtstagen identisch.","Fällt in Ihren Reisezeitraum kein Montag, Donnerstag oder Samstag, lässt sich die Tour nicht auf einen anderen Tag verlegen – es ist eine Kleingruppentour mit festem Fahrplan, keine Privatcharter."]},{"id":"pickup","title":"Abholung & Rückgabe","preview":"Zwei Abholpunkte: Station Hongik University (Ausgang 8, 08:00) und Station Myeongdong (Ausgang 2, 08:30).","content":["Zwei Abholpunkte: Station Hongik University (Ausgang 8, 08:00) und Station Myeongdong (Ausgang 2, 08:30).","Bitte treffen Sie 10 Minuten vor der Abfahrtszeit an Ihrem Treffpunkt ein.","Ihre Reiseleitung wartet mit dem Bus am Stationsausgang.","Die Rückgabe erfolgt in umgekehrter Reihenfolge: Myeongdong gegen 18:00, Station Hongik University gegen 18:30.","Die Rückkehrzeiten sind ungefähre Angaben und hängen vom Verkehr ab.","Dies ist ein Gruppenformat mit fester Route; die Reisenden gelangen selbstständig zum Treffpunkt."]},{"id":"walking","title":"Gehen & Gelände","preview":"Insgesamt mittel — etwa 5–6 km über den Tag verteilt, mit kurzen anspruchsvollen Abschnitten.","content":["Insgesamt mittel — etwa 5–6 km über den Tag verteilt, mit kurzen anspruchsvollen Abschnitten.","Sanjeong-See: flacher 3,2 km Rundweg, keine Steigung, 60–90 Min.","Jaein-Wasserfall: Die 80 m lange Hängebrücke ist eben, schwingt aber; der Holzsteg hinab zum Gumpen hat in beide Richtungen Treppen.","Pocheon Art Valley: steil von der Talstation zum Rand — das übernimmt die Monorail; der Abstieg durch den Heilwald dauert 10–15 Min.","An keiner Station ist eine Wanderung oder ein Gipfelaufstieg enthalten.","Bequeme geschlossene Schuhe empfohlen; der Holzsteg in der Schlucht kann nass sein."]},{"id":"weather","title":"Wetterregelung","preview":"Ausgeprägte jahreszeitliche Vielfalt; Ersatzprogramme sind üblich","content":["Frühling (März–Mai): An kühlen Morgen hebt sich Nebel vom Sanjeong-See, und die Schneeschmelze lässt den Jaein-Wasserfall kräftig fließen. Der Cheonjuho zeigt sein klarstes Smaragdgrün, wenn die Tage länger werden.","Sommer (Juni–August): Der Wasserfall ist am kraftvollsten, und die Schlucht bleibt mehrere Grad kühler als die Stadt. Starker Monsunregen kann die Stegabschnitte am Jaein-Wasserfall sperren — das einzige Wetterrisiko auf dieser Route.","Herbst (September–November): Die stärkste Jahreszeit hier. Silbergras färbt die Hänge des Myeongseongsan den Oktober hindurch silberweiß, der See trägt die besten Spiegelungen des Jahres, und die Granitwände des Art Valley stehen mitten im vollen Laub.","Winter (Dezember–Februar): Die ruhigste Zeit des Jahres. Der Cheonjuho kann zufrieren, am See findet das Schlittenfest statt, und der Wasserfall kann teilweise vereisen. Das Tageslicht ist kurz, der Nachmittag wird also enger getaktet, und der Holzsteg am Jaein kann rutschig sein.","Leichter Regen: Die Tour findet in der Regel statt; starker Regen kann Aufenthalte im Freien verkürzen"]},{"id":"wear","title":"Kleidung & Ausrüstung","preview":"Wanderschuhe, Zwiebellook und Extras je nach Jahreszeit","content":["Bequeme Wanderschuhe mit gutem Grip","Kleidung im Zwiebellook für die Temperaturwechsel in den Bergen","Leichte Jacke oder Windbreaker (kühler als das Zentrum von Seoul, besonders am Sanjeong-See)","Sonnenschutz im Sommer; warme Jacke und Handschuhe im Winter","Kamera oder Smartphone für die starken Fotomotive an allen drei Stationen"]},{"id":"included","title":"Enthaltene Leistungen","preview":"Hin- und Rückfahrt ab dem Zentrum von Seoul, lizenzierte englischsprachige Reiseleitung, Kraftstoff, Maut und Parkgebühren.","variant":"included","content":["Hin- und Rückfahrt ab dem Zentrum von Seoul, lizenzierte englischsprachige Reiseleitung, Kraftstoff, Maut und Parkgebühren.","Stationen mit freiem Eintritt: Sanjeong-See und sein Rundweg, Jaein-Wasserfall, Hängebrücke und Skywalk.","Nicht inbegriffen — Eintritt Pocheon Art Valley (≈ ₩6.000 Erwachsene) und Monorail (≈ ₩5.300 Erwachsene, Hin- und Rückfahrt), Tarife 2026.","Nicht inbegriffen — Mittagessen (≈ ₩15.000–20.000), Getränke, persönliche Ausgaben und Trinkgelder."]},{"id":"geopark","title":"Über den UNESCO Global Geopark","preview":"Zwei der heutigen Stationen sind ausgewiesene Geostätten.","content":["Der UNESCO Global Geopark Hantangang wurde am 7. Juli 2020 vom 209. Exekutivrat der UNESCO in Paris zertifiziert und 2024 erneut bestätigt. Er umfasst das Flussbecken des Hantangang mit Pocheon und Yeoncheon in Gyeonggi-do sowie Cheorwon in Gangwon-do.","Der Jaein-Wasserfall ist eine Geostätte: ein ≈18 m hoher Wasserfall über Säulenbasalt, mit einer vom Fluss geschnittenen Höhle, Strudeltöpfen und Gasröhren, die an seinem Fuß ablesbar sind.","Das Pocheon Art Valley ist eine Geostätte, geführt als „Art Valley und Pocheon-Stein“: das uralte Granit-Grundgebirge, über das später die Hantangang-Lava floss.","Ein UNESCO Global Geopark ist eine geologische Auszeichnung — er ist nicht dasselbe wie eine Eintragung in die UNESCO-Welterbeliste."]},{"id":"cancellation","title":"Stornierung","preview":"Kostenlose Stornierung bis 24 Stunden vor Tourbeginn.","content":["Kostenlose Stornierung bis 24 Stunden vor Tourbeginn.","Stornierungen am selben Tag und Nichterscheinen werden nicht erstattet."]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'de'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"Abholung & Rückgabe","content":["Zwei Abholpunkte: Station Hongik University (Ausgang 8, 08:00) und Station Myeongdong (Ausgang 2, 08:30).","Bitte treffen Sie 10 Minuten vor der Abfahrtszeit an Ihrem Treffpunkt ein.","Ihre Reiseleitung wartet mit dem Bus am Stationsausgang.","Die Rückgabe erfolgt in umgekehrter Reihenfolge: Myeongdong gegen 18:00, Station Hongik University gegen 18:30.","Die Rückkehrzeiten sind ungefähre Angaben und hängen vom Verkehr ab.","Dies ist ein Gruppenformat mit fester Route; die Reisenden gelangen selbstständig zum Treffpunkt."],"preview":"Zwei Abholpunkte: Station Hongik University (Ausgang 8, 08:00) und Station Myeongdong (Ausgang 2, 08:30)."},{"id":"walking","title":"Gehen & Gelände","content":["Insgesamt mittel — etwa 5–6 km über den Tag verteilt, mit kurzen anspruchsvollen Abschnitten.","Sanjeong-See: flacher 3,2 km Rundweg, keine Steigung, 60–90 Min.","Jaein-Wasserfall: Die 80 m lange Hängebrücke ist eben, schwingt aber; der Holzsteg hinab zum Gumpen hat in beide Richtungen Treppen.","Pocheon Art Valley: steil von der Talstation zum Rand — das übernimmt die Monorail; der Abstieg durch den Heilwald dauert 10–15 Min.","An keiner Station ist eine Wanderung oder ein Gipfelaufstieg enthalten.","Bequeme geschlossene Schuhe empfohlen; der Holzsteg in der Schlucht kann nass sein."],"preview":"Insgesamt mittel — etwa 5–6 km über den Tag verteilt, mit kurzen anspruchsvollen Abschnitten."},{"id":"weather","title":"Wetterregelung","content":["Frühling (März–Mai): An kühlen Morgen hebt sich Nebel vom Sanjeong-See, und die Schneeschmelze lässt den Jaein-Wasserfall kräftig fließen. Der Cheonjuho zeigt sein klarstes Smaragdgrün, wenn die Tage länger werden.","Sommer (Juni–August): Der Wasserfall ist am kraftvollsten, und die Schlucht bleibt mehrere Grad kühler als die Stadt. Starker Monsunregen kann die Stegabschnitte am Jaein-Wasserfall sperren — das einzige Wetterrisiko auf dieser Route.","Herbst (September–November): Die stärkste Jahreszeit hier. Silbergras färbt die Hänge des Myeongseongsan den Oktober hindurch silberweiß, der See trägt die besten Spiegelungen des Jahres, und die Granitwände des Art Valley stehen mitten im vollen Laub.","Winter (Dezember–Februar): Die ruhigste Zeit des Jahres. Der Cheonjuho kann zufrieren, am See findet das Schlittenfest statt, und der Wasserfall kann teilweise vereisen. Das Tageslicht ist kurz, der Nachmittag wird also enger getaktet, und der Holzsteg am Jaein kann rutschig sein.","Leichter Regen: Die Tour findet in der Regel statt; starker Regen kann Aufenthalte im Freien verkürzen"],"preview":"Ausgeprägte jahreszeitliche Vielfalt; Ersatzprogramme sind üblich"},{"id":"wear","title":"Kleidung & Ausrüstung","content":["Bequeme Wanderschuhe mit gutem Grip","Kleidung im Zwiebellook für die Temperaturwechsel in den Bergen","Leichte Jacke oder Windbreaker (kühler als das Zentrum von Seoul, besonders am Sanjeong-See)","Sonnenschutz im Sommer; warme Jacke und Handschuhe im Winter","Kamera oder Smartphone für die starken Fotomotive an allen drei Stationen"],"preview":"Wanderschuhe, Zwiebellook und Extras je nach Jahreszeit"},{"id":"included","title":"Enthaltene Leistungen","content":["Hin- und Rückfahrt ab dem Zentrum von Seoul, lizenzierte englischsprachige Reiseleitung, Kraftstoff, Maut und Parkgebühren.","Stationen mit freiem Eintritt: Sanjeong-See und sein Rundweg, Jaein-Wasserfall, Hängebrücke und Skywalk.","Nicht inbegriffen — Eintritt Pocheon Art Valley (≈ ₩6.000 Erwachsene) und Monorail (≈ ₩5.300 Erwachsene, Hin- und Rückfahrt), Tarife 2026.","Nicht inbegriffen — Mittagessen (≈ ₩15.000–20.000), Getränke, persönliche Ausgaben und Trinkgelder."],"preview":"Hin- und Rückfahrt ab dem Zentrum von Seoul, lizenzierte englischsprachige Reiseleitung, Kraftstoff, Maut und Parkgebühren.","variant":"included"},{"id":"geopark","title":"Über den UNESCO Global Geopark","content":["Der UNESCO Global Geopark Hantangang wurde am 7. Juli 2020 vom 209. Exekutivrat der UNESCO in Paris zertifiziert und 2024 erneut bestätigt. Er umfasst das Flussbecken des Hantangang mit Pocheon und Yeoncheon in Gyeonggi-do sowie Cheorwon in Gangwon-do.","Der Jaein-Wasserfall ist eine Geostätte: ein ≈18 m hoher Wasserfall über Säulenbasalt, mit einer vom Fluss geschnittenen Höhle, Strudeltöpfen und Gasröhren, die an seinem Fuß ablesbar sind.","Das Pocheon Art Valley ist eine Geostätte, geführt als „Art Valley und Pocheon-Stein“: das uralte Granit-Grundgebirge, über das später die Hantangang-Lava floss.","Ein UNESCO Global Geopark ist eine geologische Auszeichnung — er ist nicht dasselbe wie eine Eintragung in die UNESCO-Welterbeliste."],"preview":"Zwei der heutigen Stationen sind ausgewiesene Geostätten."},{"id":"cancellation","title":"Stornierung","content":["Kostenlose Stornierung bis 24 Stunden vor Tourbeginn.","Stornierungen am selben Tag und Nichterscheinen werden nicht erstattet."],"preview":"Kostenlose Stornierung bis 24 Stunden vor Tourbeginn."}]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"staticQuestions"}', '[{"question":"Was hat sich an dieser Tour geändert — war Herb Island nicht dabei?","answer":"Doch, war es. Ab August 2026 tauscht die Route Herb Island gegen den Jaein-Wasserfall in Yeoncheon und ergänzt einen richtigen lokalen Mittagsstopp. Der Grund: Der Jaein-Wasserfall und das Pocheon Art Valley sind beide Geostätten des UNESCO Global Geopark Hantangang, der Tag erzählt damit eine zusammenhängende geologische Geschichte statt drei unverbundener Stationen. Wenn Sie ausdrücklich Herb Island möchten, sprechen Sie uns vor der Buchung an — wir organisieren das gesondert."},{"question":"An welchen Wochentagen findet diese Tour statt?","answer":"Sie findet **nur montags, donnerstags und samstags** statt. Der Ablauf ist an allen drei Tagen gleich – buchen Sie einfach den Tag, der zu Ihrer Reise passt. An anderen Wochentagen wird dieses Produkt nicht angeboten."},{"question":"Was genau macht den Jaein-Wasserfall und das Art Valley „UNESCO“?","answer":"Beide sind ausgewiesene Geostätten des UNESCO Global Geopark Hantangang, zertifiziert am 7. Juli 2020 und 2024 erneut bestätigt. Es handelt sich um eine Geopark-Auszeichnung, nicht um eine Eintragung in die Welterbeliste — sie würdigt die Geologie des Hantangang-Flussbeckens in Pocheon, Yeoncheon und Cheorwon. Der Jaein-Wasserfall zeigt die Basaltlava und ihre Säulenabsonderung; das Art Valley zeigt das uralte Granit-Grundgebirge, über das die Lava floss."},{"question":"Ist die Hängebrücke am Jaein-Wasserfall gruselig? Kann ich sie auslassen?","answer":"Sie ist 80 m lang und 2 m breit und schwingt konstruktionsbedingt unter den Füßen — für die meisten Gäste ist genau das der Reiz. Sie können sie vollständig auslassen: Vom Aussichtspunkt am Schluchtrand sieht man den Wasserfall ohne Überquerung, und der Holzsteg zum Gumpen ist ein eigener Weg. Niemand bleibt zurück, wenn Sie lieber auf festem Boden bleiben."},{"question":"Ist der Eintritt inbegriffen?","answer":"Der Sanjeong-See und der Jaein-Wasserfall sind beide kostenlos. Das Pocheon Art Valley ist nicht inbegriffen — 2026 rund ₩6.000 Eintritt plus etwa ₩5.300 für eine Monorail-Hin- und -Rückfahrt für Erwachsene, mit günstigeren Tarifen für Jugendliche, Militärangehörige und Kinder. Auch das Mittagessen ist nicht inbegriffen (≈ ₩15.000–20.000). Alles Übrige — Transport, Reiseleitung, Maut und Parkgebühren — ist abgedeckt."},{"question":"Wie viel wird gelaufen, und wie anstrengend ist es?","answer":"Etwa 5–6 km über den Tag verteilt, davon der größte Teil auf dem flachen 3,2 km langen Seerundweg am Vormittag. Am Jaein-Wasserfall hat der Holzsteg hinab zum Gumpen Treppen. Das Art Valley ist von der Talstation bis zum Rand steil, was die Monorail löst — Sie fahren hinauf und gehen durch den Wald hinab. Es gibt auf dieser Tour keine Wanderung und keinen Gipfelaufstieg."},{"question":"Ist das Mittagessen inbegriffen, und welche Optionen gibt es?","answer":"Nicht inbegriffen, etwa ₩15.000–20.000. Gegessen wird in Idong, dem Bezirk von Pocheon, der Idong-Galbi (Rinderrippchen) seinen Namen gibt. Pilzgerichte und uleong — Süßwasserschnecke — sind die anderen lokalen Spezialitäten, und Idong-Makgeolli wird im selben Tal gebraut. Sagen Sie Ihrer Reiseleitung Bescheid, wenn Sie vegetarische Optionen brauchen, dann führt sie Sie zum richtigen Lokal."},{"question":"Worin unterscheidet sich das von einem Tagesausflug zur Insel Nami?","answer":"Die Insel Nami ist ein einzelnes, sehr beliebtes Ziel, das man per Fähre erreicht. Diese Route bietet drei wirklich unterschiedliche Landschaften — einen hundert Jahre alten Stausee, eine Basalt-Wasserfallschlucht und einen gefluteten Granitsteinbruch — in einem Teil von Gyeonggi, der nur einen Bruchteil von Namis Besucherandrang sieht, mit einem UNESCO Global Geopark als roter Faden durch den Nachmittag."},{"question":"Lohnt sich das im Winter?","answer":"Ja, mit Abstrichen. Der zugefrorene Cheonjuho im Art Valley gehört zu den schönsten Anblicken des Geländes, am See findet ein Schlittenfest statt, und jede Station ist so ruhig wie nie. Dagegen steht: Das Tageslicht ist kurz, der Nachmittag wird also enger getaktet, und der Holzsteg am Jaein-Wasserfall kann vereist sein. Mit passender Kleidung ist es ein starker Wintertag."},{"question":"Was passiert, wenn es regnet?","answer":"Die Tour findet statt. Der Seerundweg und das Art Valley sind mit Schirm gut machbar, und Regen verstärkt den Jaein-Wasserfall sogar. Die einzige echte Ausnahme ist starker Sommerregen, wenn die Stegabschnitte an der Schlucht aus Sicherheitsgründen gesperrt werden können — in diesem Fall verlängern wir die übrigen Stationen, statt den Tag abzusagen."},{"question":"Wo findet die Abholung und die Rückgabe statt?","answer":"Zwei Treffpunkte in Seoul: Station Hongik University (Ausgang 8) um 08:00 und Station Myeongdong (Ausgang 2) um 08:30. Bitte treffen Sie 10 Minuten vor Ihrer Abfahrtszeit ein — die Reiseleitung wartet mit dem Bus am Ausgang. Die Rückfahrt erfolgt in umgekehrter Reihenfolge: Myeongdong gegen 18:00 und Station Hongik University gegen 18:30, je nach Verkehr."},{"question":"Ist das für Kinder oder ältere Gäste geeignet?","answer":"Für die meisten ja. Der Seerundweg ist flach, und die Monorail nimmt dem Art Valley den Aufstieg. Abzuwägen sind zwei Dinge: die Treppen am Holzsteg des Jaein-Wasserfalls und die schwingende Hängebrücke — beides ist optional, und der Aussichtspunkt am Schluchtrand zeigt den Wasserfall auch allen, die lieber verzichten. Es ist ein 10-Stunden-Tag, er passt also besser zu aktiven älteren Reisenden als zu jemandem, der häufige Pausen braucht."},{"question":"Kann ich das stattdessen mit öffentlichen Verkehrsmitteln machen?","answer":"Das wäre schwierig. Der Sanjeong-See, der Jaein-Wasserfall und das Art Valley liegen in drei verschiedenen Bezirken über zwei Landkreise verteilt, und Busse zum Art Valley fahren nur alle paar Stunden. Alle drei an einem Tag ohne Fahrzeug zu schaffen, ist nicht realistisch — was der Hauptgrund dafür ist, dass es diese Route als Tour gibt."}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'de'
  AND detail_payload #> '{"staticQuestions"}' IS NOT DISTINCT FROM '[{"answer":"Doch, war es. Ab August 2026 tauscht die Route Herb Island gegen den Jaein-Wasserfall in Yeoncheon und ergänzt einen richtigen lokalen Mittagsstopp. Der Grund: Der Jaein-Wasserfall und das Pocheon Art Valley sind beide Geostätten des UNESCO Global Geopark Hantangang, der Tag erzählt damit eine zusammenhängende geologische Geschichte statt drei unverbundener Stationen. Wenn Sie ausdrücklich Herb Island möchten, sprechen Sie uns vor der Buchung an — wir organisieren das gesondert.","question":"Was hat sich an dieser Tour geändert — war Herb Island nicht dabei?"},{"answer":"Beide sind ausgewiesene Geostätten des UNESCO Global Geopark Hantangang, zertifiziert am 7. Juli 2020 und 2024 erneut bestätigt. Es handelt sich um eine Geopark-Auszeichnung, nicht um eine Eintragung in die Welterbeliste — sie würdigt die Geologie des Hantangang-Flussbeckens in Pocheon, Yeoncheon und Cheorwon. Der Jaein-Wasserfall zeigt die Basaltlava und ihre Säulenabsonderung; das Art Valley zeigt das uralte Granit-Grundgebirge, über das die Lava floss.","question":"Was genau macht den Jaein-Wasserfall und das Art Valley „UNESCO“?"},{"answer":"Sie ist 80 m lang und 2 m breit und schwingt konstruktionsbedingt unter den Füßen — für die meisten Gäste ist genau das der Reiz. Sie können sie vollständig auslassen: Vom Aussichtspunkt am Schluchtrand sieht man den Wasserfall ohne Überquerung, und der Holzsteg zum Gumpen ist ein eigener Weg. Niemand bleibt zurück, wenn Sie lieber auf festem Boden bleiben.","question":"Ist die Hängebrücke am Jaein-Wasserfall gruselig? Kann ich sie auslassen?"},{"answer":"Der Sanjeong-See und der Jaein-Wasserfall sind beide kostenlos. Das Pocheon Art Valley ist nicht inbegriffen — 2026 rund ₩6.000 Eintritt plus etwa ₩5.300 für eine Monorail-Hin- und -Rückfahrt für Erwachsene, mit günstigeren Tarifen für Jugendliche, Militärangehörige und Kinder. Auch das Mittagessen ist nicht inbegriffen (≈ ₩15.0