  detail_payload = jsonb_set(detail_payload, '{"catalog_card","badges"}', '["Excursion depuis Séoul","Lun · jeu · sam","Géoparc UNESCO","Cascade","Balade au bord du lac","Petit groupe"]'::jsonb, true),
