WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'fr'
  AND detail_payload #> '{"catalog_card","badges"}' IS NOT DISTINCT FROM '["Excursion depuis Séoul","Géoparc UNESCO","Cascade","Balade au bord du lac","Petit groupe"]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"catalog_card","shortCardDescription"}', '"Une excursion d''une journée plus paisible au départ de Séoul, bâtie sur une géologie bien réelle. Vous parcourez la boucle plate de 3,2 km autour du lac Sanjeong, au pied du mont Myeongseongsan, goûtez l''Idong galbi dont Pocheon a fait sa spécialité, puis traversez un pont suspendu de 80 m pour faire face à la cascade de Jaein, qui tombe de 18 m sur des orgues basaltiques, avant de terminer au cœur de la carrière de granit de Pocheon Art Valley, où l''eau de source a rempli la fosse pour former le lac émeraude de Cheonjuho. La cascade de Jaein et Art Valley sont toutes deux des géosites du Géoparc mondial UNESCO du Hantangang — un même paysage vu de ses deux moitiés opposées. Départs les lundis, jeudis et samedis."'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'fr'
  AND detail_payload #>> '{"catalog_card","shortCardDescription"}' IS NOT DISTINCT FROM 'Une excursion d''une journée plus paisible au départ de Séoul, bâtie sur une géologie bien réelle. Vous parcourez la boucle plate de 3,2 km autour du lac Sanjeong, au pied du mont Myeongseongsan, goûtez l''Idong galbi dont Pocheon a fait sa spécialité, puis traversez un pont suspendu de 80 m pour faire face à la cascade de Jaein, qui tombe de 18 m sur des orgues basaltiques, avant de terminer au cœur de la carrière de granit de Pocheon Art Valley, où l''eau de source a rempli la fosse pour former le lac émeraude de Cheonjuho. La cascade de Jaein et Art Valley sont toutes deux des géosites du Géoparc mondial UNESCO du Hantangang — un même paysage vu de ses deux moitiés opposées.';

