UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"Jours de départ","preview":"Ce circuit part **uniquement les lundis, jeudis et samedis** — merci de réserver l''une de ces dates.","content":["Ce circuit part **uniquement les lundis, jeudis et samedis** — merci de réserver l''une de ces dates.","L''itinéraire, les horaires et les deux points de prise en charge sont identiques les trois jours de départ.","Si vos dates ne comportent ni lundi, ni jeudi, ni samedi, le circuit ne peut pas être déplacé à un autre jour : il s''agit d''un départ en petit groupe à horaires fixes, et non d''un véhicule privé."]},{"id":"pickup","title":"Prise en charge et retour","preview":"Deux points de ramassage : la station Hongik University (sortie 8, 08:00) et la station Myeongdong (sortie 2, 08:30).","content":["Deux points de ramassage : la station Hongik University (sortie 8, 08:00) et la station Myeongdong (sortie 2, 08:30).","Merci d''arriver à votre point de rendez-vous 10 minutes avant l''heure de départ.","Votre guide vous attend à la sortie de la station avec le bus.","Les déposes suivent l''ordre inverse : Myeongdong vers 18:00, la station Hongik University vers 18:30.","Les heures de retour sont approximatives et dépendent de la circulation.","Il s''agit d''une formule en groupe à itinéraire fixe ; les voyageurs se rendent eux-mêmes au point de rendez-vous."]},{"id":"walking","title":"Marche et terrain","preview":"Modéré dans l''ensemble — environ 5–6 km sur la journée, avec de courtes sections exigeantes.","content":["Modéré dans l''ensemble — environ 5–6 km sur la journée, avec de courtes sections exigeantes.","Lac Sanjeong : boucle plate de 3,2 km, sans montée, 60–90 min.","Cascade de Jaein : le pont suspendu de 80 m est plat mais il oscille ; le ponton qui descend vers la vasque comporte des escaliers à l''aller comme au retour.","Pocheon Art Valley : pente raide de la base au rebord — le monorail s''en charge ; la descente par la Forêt de bien-être prend 10–15 min.","Aucune randonnée ni ascension de sommet n''est comprise, à aucune étape.","Chaussures fermées et confortables recommandées ; le ponton de la gorge peut être mouillé."]},{"id":"weather","title":"Politique météo","preview":"Fortes variations saisonnières ; les substitutions sont fréquentes","content":["Printemps (mars–mai): La brume se lève du lac Sanjeong les matins frais, et la fonte des neiges maintient un fort débit à la cascade de Jaein. Le Cheonjuho affiche son émeraude le plus limpide à mesure que les jours s''allongent.","Été (juin–août): La cascade est à sa puissance maximale, et la gorge reste de plusieurs degrés plus fraîche que la ville. Les fortes pluies de mousson peuvent fermer les sections de ponton de la cascade de Jaein — le seul risque météo de cet itinéraire.","Automne (septembre–novembre): La plus belle saison ici. L''herbe argentée blanchit les pentes du Myeongseongsan tout au long d''octobre, le lac offre les plus beaux reflets de l''année, et les parois de granit d''Art Valley se dressent au cœur d''un feuillage flamboyant.","Hiver (décembre–février): L''affluence la plus faible de l''année. Le Cheonjuho peut geler, le lac accueille son festival de luge et la cascade peut se figer partiellement. Les jours sont courts, l''après-midi est donc plus serré et le ponton de Jaein peut être glissant.","Pluie légère : le circuit est généralement maintenu ; une forte pluie peut écourter les étapes en extérieur"]},{"id":"wear","title":"Quoi porter et emporter","preview":"Chaussures de marche, plusieurs couches et accessoires de saison","content":["Chaussures de marche confortables et antidérapantes","Vêtements en plusieurs couches pour les écarts de température en montagne","Veste légère ou coupe-vent (il fait plus frais qu''au centre de Séoul, en particulier au lac Sanjeong)","Protection solaire en été ; veste chaude et gants en hiver","Appareil photo ou téléphone pour les belles occasions de photo aux trois étapes"]},{"id":"included","title":"Ce qui est inclus","preview":"Transport aller-retour depuis le centre de Séoul, guide anglophone agréé, carburant, péages et stationnement.","variant":"included","content":["Transport aller-retour depuis le centre de Séoul, guide anglophone agréé, carburant, péages et stationnement.","Étapes à entrée gratuite : le lac Sanjeong et son sentier en boucle, la cascade de Jaein, le pont suspendu et la passerelle de verre.","Non inclus — l''entrée de Pocheon Art Valley (≈ ₩6 000 adulte) et le monorail (≈ ₩5 300 l''aller-retour adulte), tarifs 2026.","Non inclus — le déjeuner (≈ ₩15 000–20 000), les boissons, les dépenses personnelles et les pourboires."]},{"id":"geopark","title":"À propos du Géoparc mondial UNESCO","preview":"Deux des étapes du jour sont des géosites désignés.","content":["Le Géoparc mondial UNESCO du Hantangang a été certifié le 7 juillet 2020 par la 209e session du Conseil exécutif de l''UNESCO, à Paris, et reconduit en 2024. Il couvre le bassin de la rivière Hantangang, sur les communes de Pocheon et Yeoncheon dans le Gyeonggi-do et de Cheorwon dans le Gangwon-do.","La cascade de Jaein est un géosite : une chute d''environ 18 m sur des orgues basaltiques, avec une grotte creusée par la rivière, des marmites de géant et des tubes de gaz lisibles à sa base.","Pocheon Art Valley est un géosite inscrit sous le nom d''« Art Valley et pierre de Pocheon » : l''ancien socle de granit sur lequel la lave du Hantangang s''est plus tard écoulée.","Un Géoparc mondial UNESCO est un label géologique — ce n''est pas la même chose qu''une inscription au patrimoine mondial de l''UNESCO."]},{"id":"cancellation","title":"Annulation","preview":"Annulation gratuite jusqu''à 24 heures avant le début du circuit.","content":["Annulation gratuite jusqu''à 24 heures avant le début du circuit.","Les annulations le jour même et les absences ne sont pas remboursables."]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'fr'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"Prise en charge et retour","content":["Deux points de ramassage : la station Hongik University (sortie 8, 08:00) et la station Myeongdong (sortie 2, 08:30).","Merci d''arriver à votre point de rendez-vous 10 minutes avant l''heure de départ.","Votre guide vous attend à la sortie de la station avec le bus.","Les déposes suivent l''ordre inverse : Myeongdong vers 18:00, la station Hongik University vers 18:30.","Les heures de retour sont approximatives et dépendent de la circulation.","Il s''agit d''une formule en groupe à itinéraire fixe ; les voyageurs se rendent eux-mêmes au point de rendez-vous."],"preview":"Deux points de ramassage : la station Hongik University (sortie 8, 08:00) et la station Myeongdong (sortie 2, 08:30)."},{"id":"walking","title":"Marche et terrain","content":["Modéré dans l''ensemble — environ 5–6 km sur la journée, avec de courtes sections exigeantes.","Lac Sanjeong : boucle plate de 3,2 km, sans montée, 60–90 min.","Cascade de Jaein : le pont suspendu de 80 m est plat mais il oscille ; le ponton qui descend vers la vasque comporte des escaliers à l''aller comme au retour.","Pocheon Art Valley : pente raide de la base au rebord — le monorail s''en charge ; la descente par la Forêt de bien-être prend 10–15 min.","Aucune randonnée ni ascension de sommet n''est comprise, à aucune étape.","Chaussures fermées et confortables recommandées ; le ponton de la gorge peut être mouillé."],"preview":"Modéré dans l''ensemble — environ 5–6 km sur la journée, avec de courtes sections exigeantes."},{"id":"weather","title":"Politique météo","content":["Printemps (mars–mai): La brume se lève du lac Sanjeong les matins frais, et la fonte des neiges maintient un fort débit à la cascade de Jaein. Le Cheonjuho affiche son émeraude le plus limpide à mesure que les jours s''allongent.","Été (juin–août): La cascade est à sa puissance maximale, et la gorge reste de plus