UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"catalog_card","shortCardDescription"}', '"Una gita di un giorno da Seoul più tranquilla, costruita sulla geologia vera. Percorra l''anello pianeggiante di 3,2 km attorno al lago Sanjeong ai piedi del monte Myeongseongsan, assaggi l''Idong galbi, il piatto di Pocheon, poi attraversi un ponte sospeso di 80 m per trovarsi di fronte alla cascata di Jaein mentre precipita per 18 m su colonne basaltiche, e concluda dentro la cava di granito del Pocheon Art Valley, dove l''acqua sorgiva ha riempito lo scavo formando il lago Cheonjuho color smeraldo. La cascata di Jaein e Art Valley sono entrambe geositi del Geoparco mondiale UNESCO dell''Hantangang: lo stesso paesaggio visto dalle sue due metà opposte. Partenze il lunedì, il giovedì e il sabato."'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'it'
  AND detail_payload #>> '{"catalog_card","shortCardDescription"}' IS NOT DISTINCT FROM 'Una gita di un giorno da Seoul più tranquilla, costruita sulla geologia vera. Percorra l''anello pianeggiante di 3,2 km attorno al lago Sanjeong ai piedi del monte Myeongseongsan, assaggi l''Idong galbi, il piatto di Pocheon, poi attraversi un ponte sospeso di 80 m per trovarsi di fronte alla cascata di Jaein mentre precipita per 18 m su colonne basaltiche, e concluda dentro la cava di granito del Pocheon Art Valley, dove l''acqua sorgiva ha riempito lo scavo formando il lago Cheonjuho color smeraldo. La cascata di Jaein e Art Valley sono entrambe geositi del Geoparco mondiale UNESCO dell''Hantangang: lo stesso paesaggio visto dalle sue due metà opposte.';

