UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"Giorni di partenza","preview":"Questo tour parte **solo il lunedì, il giovedì e il sabato**: prenoti una di queste date.","content":["Questo tour parte **solo il lunedì, il giovedì e il sabato**: prenoti una di queste date.","Percorso, orari ed entrambi i punti di ritrovo sono identici in tutti e tre i giorni di partenza.","Se le sue date non comprendono un lunedì, un giovedì o un sabato, il tour non può essere spostato ad altro giorno: è una partenza in piccolo gruppo a calendario fisso, non un noleggio privato."]},{"id":"pickup","title":"Ritrovo e rientro","preview":"Due punti di ritrovo: stazione Hongik University (uscita 8, 08:00) e stazione Myeongdong (uscita 2, 08:30).","content":["Due punti di ritrovo: stazione Hongik University (uscita 8, 08:00) e stazione Myeongdong (uscita 2, 08:30).","La preghiamo di arrivare al punto di ritrovo 10 minuti prima dell''orario di partenza.","La sua guida attende all''uscita della stazione con il bus.","Il rientro segue l''ordine inverso: Myeongdong verso le 18:00, stazione Hongik University verso le 18:30.","Gli orari di rientro sono approssimativi e dipendono dal traffico.","Si tratta di una formula di gruppo a itinerario fisso; i viaggiatori raggiungono da soli il punto di ritrovo."]},{"id":"walking","title":"Camminata e terreno","preview":"Moderata nel complesso — circa 5–6 km nell''arco della giornata, con brevi tratti più impegnativi.","content":["Moderata nel complesso — circa 5–6 km nell''arco della giornata, con brevi tratti più impegnativi.","Lago Sanjeong: anello pianeggiante di 3,2 km, nessuna salita, 60–90 min.","Cascata di Jaein: il ponte sospeso di 80 m è pianeggiante ma oscilla; il camminamento in discesa verso la pozza ha scale in entrambi i sensi.","Pocheon Art Valley: ripido dalla base al bordo della cava — ci pensa la monorotaia; la discesa a piedi nell''Healing Forest richiede 10–15 min.","In nessuna tappa sono previste escursioni in montagna o salite in vetta.","Si consigliano scarpe chiuse e comode; il camminamento della gola può essere bagnato."]},{"id":"weather","title":"Politica in caso di maltempo","preview":"Forte varietà stagionale; le sostituzioni sono frequenti","content":["Primavera (mar–mag): La foschia si alza dal lago Sanjeong nelle mattine fresche e lo scioglimento delle nevi mantiene potente la cascata di Jaein. Il Cheonjuho mostra il suo smeraldo più limpido man mano che le giornate si allungano.","Estate (giu–ago): La cascata è al massimo della potenza e nella gola si sta diversi gradi più freschi che in città. Le piogge intense del monsone possono chiudere i tratti di camminamento della cascata di Jaein: è l''unico rischio meteorologico di questo itinerario.","Autunno (set–nov): Qui è la stagione più bella. L''erba argentata tinge di bianco argenteo i pendii del Myeongseongsan per tutto ottobre, il lago offre i riflessi migliori dell''anno e le pareti di granito di Art Valley si incastonano nel pieno del foliage.","Inverno (dic–feb): L''affluenza più bassa dell''anno. Il Cheonjuho può gelare, il lago ospita il suo festival dello slittino e la cascata può ghiacciare in parte. Le giornate sono corte, quindi il pomeriggio è più serrato e il camminamento di Jaein può essere scivoloso.","Pioggia leggera: il tour di norma si svolge; la pioggia intensa può accorciare le soste all''aperto"]},{"id":"wear","title":"Che cosa indossare e portare","preview":"Scarpe da camminata, abbigliamento a strati ed extra stagionali","content":["Scarpe da camminata comode e con buona aderenza","Abbigliamento a strati per gli sbalzi di temperatura in montagna","Giacca leggera o giacca a vento (fa più fresco che nel centro di Seoul, soprattutto al lago Sanjeong)","Protezione solare in estate; giacca calda e guanti in inverno","Macchina fotografica o telefono per le ottime occasioni fotografiche in tutte e tre le tappe"]},{"id":"included","title":"Che cosa è incluso","preview":"Trasporto andata e ritorno dal centro di Seoul, guida abilitata di lingua inglese, carburante, pedaggi e parcheggi.","variant":"included","content":["Trasporto andata e ritorno dal centro di Seoul, guida abilitata di lingua inglese, carburante, pedaggi e parcheggi.","Tappe a ingresso gratuito: il lago Sanjeong e il suo sentiero ad anello, la cascata di Jaein, il ponte sospeso e lo skywalk.","Non incluso — ingresso al Pocheon Art Valley (≈ ₩6.000 adulti) e monorotaia (≈ ₩5.300 andata e ritorno per adulto), tariffe 2026.","Non inclusi — pranzo (≈ ₩15.000–20.000), bevande, spese personali e mance."]},{"id":"geopark","title":"Il Geoparco mondiale UNESCO","preview":"Due delle tappe di oggi sono geositi designati.","content":["Il Geoparco mondiale UNESCO dell''Hantangang è stato certificato il 7 luglio 2020 dalla 209ª sessione del Consiglio esecutivo dell''UNESCO a Parigi ed è stato riconfermato nel 2024. Comprende il bacino del fiume Hantangang fra Pocheon e Yeoncheon, nel Gyeonggi-do, e Cheorwon, nel Gangwon-do.","La cascata di Jaein è un geosito: una cascata di ≈18 m su disgiunzioni colonnari basaltiche, con una grotta scavata dal fiume, marmitte dei giganti e tubi di gas leggibili alla sua base.","Il Pocheon Art Valley è un geosito elencato come «Art Valley e pietra di Pocheon»: l''antica roccia del basamento granitico su cui in seguito è scorsa la lava dell''Hantangang.","Un Geoparco mondiale UNESCO è una designazione geologica: non equivale a un''iscrizione nella lista del Patrimonio mondiale dell''UNESCO."]},{"id":"cancellation","title":"Cancellazione","preview":"Cancellazione gratuita fino a 24 ore prima dell''inizio del tour.","content":["Cancellazione gratuita fino a 24 ore prima dell''inizio del tour.","Le cancellazioni in giornata e le mancate presentazioni non sono rimborsabili."]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'it'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"Ritrovo e rientro","content":["Due punti di ritrovo: stazione Hongik University (uscita 8, 08:00) e stazione Myeongdong (uscita 2, 08:30).","La preghiamo di arrivare al punto di ritrovo 10 minuti prima dell''orario di partenza.","La sua guida attende all''uscita della stazione con il bus.","Il rientro segue l''ordine inverso: Myeongdong verso le 18:00, stazione Hongik University verso le 18:30.","Gli orari di rientro sono approssimativi e dipendono dal traffico.","Si tratta di una formula di gruppo a itinerario fisso; i viaggiatori raggiungono da soli il punto di ritrovo."],"preview":"Due punti di ritrovo: stazione Hongik University (uscita 8, 08:00) e stazione Myeongdong (uscita 2, 08:30)."},{"id":"walking","title":"Camminata e terreno","content":["Moderata nel complesso — circa 5–6 km nell''arco della giornata, con brevi tratti più impegnativi.","Lago Sanjeong: anello pianeggiante di 3,2 km, nessuna salita, 60–90 min.","Cascata di Jaein: il ponte sospeso di 80 m è pianeggiante ma oscilla; il camminamento in discesa verso la pozza ha scale in entrambi i sensi.","Pocheon Art Valley: ripido dalla base al bordo della cava — ci pensa la monorotaia; la discesa a piedi nell''Healing Forest richiede 10–15 min.","In nessuna tappa sono previste escursioni in montagna o salite in vetta.","Si consigliano scarpe chiuse e comode; il camminamento della gola può essere bagnato."],"preview":"Moderata nel complesso — circa 5–6 km nell''arco della giornata, con brevi tratti più impegnativi."},{"id":"weather","title":"Politica in caso di maltempo","content":["Primavera (mar–mag): La foschia si alza dal lago Sanjeong nelle mattine fresche e lo scioglimento delle nevi mantiene potente la cascata di Jaein. Il Cheonjuho mostra il suo smeraldo più limpido man mano che le giornate si allungano.","Estate (giu–ago): La cascata è al massimo della potenza e nella gola si sta diversi gradi più freschi che in città. Le piogge intense del monsone possono chiudere i tratti di camminamento della cascata di Jaein: è l''unico rischio meteorologico di questo itinerario.","Autunno (set–nov): Qui è la stagione più bella. L''erba argentata tinge di bianco argenteo i pendii del Myeongseongsan per tutto ottobre, il lago offre i riflessi migliori dell''anno e le pareti di granito di Art Valley si incastonano nel pieno del foliage.","Inverno (dic–feb): L''affluenza più bassa dell''anno. Il Cheonjuho può gelare, il lago ospita il suo festival dello slittino e la cascata può ghiacciare in parte. Le giornate sono corte, quindi il pomeriggio è più serrato e il camminamento di Jaein può essere scivoloso.","Pioggia leggera: il tour di norma si svolge; la pioggia intensa può accorciare le soste all''aperto"],"preview":"Forte varietà stagionale; le sostituzioni sono frequenti"},{"id":"wear","title":"Che cosa indossare e portare","content":["Scarpe da camminata comode e con buona aderenza","Abbigliamento a strati per gli sbalzi di temperatura in montagna","Giacca leggera o giacca a vento (fa più fresco che nel centro di Seoul, soprattutto al lago Sanjeong)","Protezione solare in estate; giacca calda e guanti in inverno","Macchina fotografica o telefono per le ottime occasioni fotografiche in tutte e tre le tappe"],"preview":"Scarpe da camminata, abbigliamento a strati ed extra stagionali"},{"id":"included","title":"Che cosa è incluso","content":["Trasporto andata e ritorno dal centro di Seoul, guida abilitata di lingua inglese, carburante, pedaggi e parcheggi.","Tappe a ingresso gratuito: il lago Sanjeong e il suo sentiero ad anello, la cascata di Jaein, il ponte sospeso e lo skywalk.","Non incluso — ingresso al Pocheon Art Valley (≈ ₩6.000 adulti) e monorotaia (≈ ₩5.300 andata e ritorno per adulto), tariffe 2026.","Non inclusi — pranzo (≈ ₩15.000–20.000), bevande, spese personali e mance."],"preview":"Trasporto andata e ritorno dal centro di Seoul, guida abilitata di lingua inglese, carburante, pedaggi e parcheggi.","variant":"included"},{"id":"geopark","title":"Il Geoparco mondiale UNESCO","content":["Il Geoparco mondiale UNESCO dell''Hantangang è stato certificato il 7 luglio 2020 dalla 209ª sessione del Consiglio esecutivo dell''UNESCO a Parigi ed è stato riconfermato nel 2024. Comprende il bacino del fiume Hantangang fra Pocheon e Yeoncheon, nel Gyeonggi-do, e Cheorwon, nel Gangwon-do.","La cascata di Jaein è un geosito: una cascata di ≈18 m su disgiunzioni colonnari basaltiche, con una grotta scavata dal fiume, marmitte dei giganti e tubi di gas leggibili alla sua base.","Il Pocheon Art Valley è un geosito elencato come «Art Valley e pietra di Pocheon»: l''antica roccia del basamento granitico su cui in seguito è scorsa la lava dell''Hantangang.","Un Geoparco mondiale UNESCO è una designazione geologica: non equivale a un''iscrizione nella lista del Patrimonio mondiale dell''UNESCO."],"preview":"Due delle tappe di oggi sono geositi designati."},{"id":"cancellation","title":"Cancellazione","content":["Cancellazione gratuita fino a 24 ore prima dell''inizio del tour.","Le cancellazioni in giornata e le mancate presentazioni non sono rimborsabili."],"preview":"Cancellazione gratuita fino a 24 ore prima dell''inizio del tour."}]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"staticQuestions"}', '[{"question":"Che cosa è cambiato in questo tour? Non comprendeva Herb Island?","answer":"Sì, la comprendeva. Da agosto 2026 l''itinerario sostituisce Herb Island con la cascata di Jaein, nella contea di Yeoncheon, e aggiunge una vera sosta pranzo locale. Il motivo è che la cascata di Jaein e il Pocheon Art Valley sono entrambi geositi del Geoparco mondiale UNESCO dell''Hantangang, così la giornata racconta ora un''unica storia geologica coerente invece di tre tappe scollegate. Se desidera espressamente Herb Island, ci contatti prima di prenotare: la organizziamo come soluzione separata."},{"question":"In quali giorni della settimana opera questo tour?","answer":"Opera **solo il lunedì, il giovedì e il sabato**. L''itinerario è identico in tutti e tre i giorni, quindi può prenotare quello più comodo per il suo viaggio. Negli altri giorni questo prodotto non è disponibile."},{"question":"Che cosa rende «UNESCO» la cascata di Jaein e Art Valley?","answer":"Entrambi sono geositi designati del Geoparco mondiale UNESCO dell''Hantangang, certificato il 7 luglio 2020 e riconfermato nel 2024. Si tratta di una designazione di geoparco, non di un''iscrizione nella lista del Patrimonio mondiale: riconosce la geologia del bacino del fiume Hantangang fra Pocheon, Yeoncheon e Cheorwon. La cascata di Jaein mostra la lava basaltica e le sue disgiunzioni colonnari; Art Valley mostra l''antico basamento granitico su cui la lava è scorsa."},{"question":"Il ponte sospeso della cascata di Jaein fa paura? Posso saltarlo?","answer":"È lungo 80 m e largo 2 m e oscilla davvero sotto i piedi, per scelta progettuale: per la maggior parte degli ospiti è proprio questo il bello. Può evitarlo del tutto: il punto panoramico sul ciglio permette di vedere la cascata senza attraversare, e il camminamento verso la pozza è un percorso separato. Nessuno viene lasciato indietro se preferisce restare sulla terraferma."},{"question":"L''ingresso è incluso?","answer":"Il lago Sanjeong e la cascata di Jaein sono entrambi gratuiti. Il Pocheon Art Valley non è incluso: nel 2026 all''incirca ₩6.000 di ingresso più circa ₩5.300 per un''andata e ritorno in monorotaia per un adulto, con tariffe ridotte per ragazzi, militari e bambini. Anche il pranzo non è incluso (≈ ₩15.000–20.000). Tutto il resto — trasporto, guida, pedaggi e parcheggi — è compreso."},{"question":"Quanto si cammina e quanto è impegnativo?","answer":"Circa 5–6 km nell''arco della giornata, in gran parte l''anello pianeggiante di 3,2 km attorno al lago, al mattino. Alla cascata di Jaein ci sono scale sul camminamento in discesa verso la pozza. Art Valley è ripido dalla base al bordo della cava, e la monorotaia risolve il problema: si sale in monorotaia e si scende a piedi attraverso il bosco. Questo tour non prevede né escursioni in montagna né salite in vetta."},{"question":"Il pranzo è incluso e quali sono le opzioni?","answer":"Non è incluso, circa ₩15.000–20.000. Il pranzo è a Idong, il distretto di Pocheon che dà il nome all''Idong galbi (costine di manzo). I piatti a base di funghi e l''uleong — lumaca d''acqua dolce — sono le altre specialità locali, e il makgeolli di Idong viene prodotto nella stessa valle. Dica alla sua guida se le servono opzioni vegetariane e le indicherà il locale giusto."},{"question":"In che cosa è diverso da una gita di un giorno all''isola di Nami?","answer":"L''isola di Nami è una singola destinazione, molto popolare, raggiungibile in traghetto. Questo itinerario propone tre paesaggi davvero diversi — un bacino centenario, una gola con cascata basaltica e una cava di granito allagata — in una zona del Gyeonggi che vede una frazione della folla di Nami, con il filo conduttore di un Geoparco mondiale UNESCO che attraversa tutto il pomeriggio."},{"question":"Ne vale la pena in inverno?","answer":"Sì, con qualche compromesso. Il Cheonjuho che gela ad Art Valley è una delle viste più belle del sito, il lago ospita un festival dello slittino e ogni tappa è nel suo momento più tranquillo. Di contro: le giornate sono corte, quindi il pomeriggio è più serrato, e il camminamento della cascata di Jaein può essere ghiacciato. Con l''abbigliamento giusto è un''ottima giornata invernale."},{"question":"Che cosa succede se piove?","answer":"Il tour si svolge comunque. L''anello del lago e Art Valley si affrontano bene con un ombrello, e la pioggia anzi rende più potente la cascata di Jaein. L''unica vera eccezione sono le piogge intense estive, quando i tratti di camminamento della gola possono essere chiusi per sicurezza: in quel caso prolunghiamo le altre tappe invece di annullare la giornata."},{"question":"Dove avvengono il ritrovo e il rientro?","answer":"Due punti di ritrovo a Seoul: stazione Hongik University (uscita 8) alle 08:00 e stazione Myeongdong (uscita 2) alle 08:30. La preghiamo di arrivare 10 minuti prima del suo orario di partenza: la guida la attende all''uscita con il bus. Il rientro segue l''ordine inverso: Myeongdong verso le 18:00 e la stazione Hongik University verso le 18:30, a seconda del traffico."},{"question":"È adatto ai bambini o alle persone anziane?","answer":"Per la maggior parte, sì. L''anello del lago è pianeggiante e la monorotaia elimina la salita di Art Valley. I due elementi da valutare sono le scale del camminamento alla cascata di Jaein e l''oscillazione del ponte sospeso: entrambi sono facoltativi, e il punto panoramico sul ciglio regala la cascata anche a chi preferisce evitarli. È una giornata di 10 ore, quindi si addice più a viaggiatori anziani attivi che a chi ha bisogno di riposare spesso."},{"question":"Posso farlo con i mezzi pubblici?","answer":"Sarebbe difficile. Il lago Sanjeong, la cascata di Jaein e Art Valley si trovano in tre distretti diversi, a cavallo di due contee, e gli autobus per Art Valley passano solo ogni due ore circa. Fare tutte e tre le tappe in una giornata senza un mezzo proprio non è realistico: è gran parte del motivo per cui questo itinerario esiste come tour."}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'it'
  AND detail_payload #> '{"staticQuestions"}' IS NOT DISTINCT FROM '[{"answer":"Sì, la comprendeva. Da agosto 2026 l''itinerario sostituisce Herb Island con la cascata di Jaein, nella contea di Yeoncheon, e aggiunge una vera sosta pranzo locale. Il motivo è che la cascata di Jaein e il Pocheon Art Valley sono entrambi geositi del Geoparco mondiale UNESCO dell''Hantangang, così la giornata racconta ora un''unica storia geologica coerente invece di tre tappe scollegate. Se desidera espressamente Herb Island, ci contatti prima di prenotare: la organizziamo come soluzione separata.","question":"Che cosa è cambiato in questo tour? Non comprendeva Herb Island?"},{"answer":"Entrambi sono geositi designati del Geoparco mondiale UNESCO dell''Hantangang, certificato il 7 luglio 2020 e riconfermato nel 2024. Si tratta di una designazione di geoparco, non di un''iscrizione nella lista del Patrimonio mondiale: riconosce la geologia del bacino del fiume Hantangang fra Pocheon, Yeoncheon e Cheorwon. La cascata di Jaein mostra la lava basaltica e le sue disgiunzioni colonnari; Art Valley mostra l''antico basamento granitico su cui la lava è scorsa.","question":"Che cosa rende «UNESCO» la cascata di Jaein e Art Valley?"},{"answer":"È lungo 80 m e largo 2 m e oscilla davvero sotto i piedi, per scelta progettuale: per la maggior parte degli ospiti è proprio questo il bello. Può evitarlo del tutto: il punto panoramico sul ciglio permette di vedere la cascata senza attraversare, e il camminamento verso la pozza è un percorso separato. Nessuno viene lasciato indietro se preferisce restare sulla terraferma.","question":"Il ponte sospeso della cascata di Jaein fa paura? Posso saltarlo?"},{"answer":"Il lago Sanjeong e la cascata di Jaein sono entrambi gratuiti. Il Pocheon Art Valley non è incluso: nel 2026 all''incirca ₩6.000 di ingresso più circa ₩5.300 per un''andata e ritorno in monorotaia per un adulto, con tariffe ridotte per ragazzi, militari e bambini. Anche il pranzo non è incluso (≈ ₩15.000–20.000). Tutto il resto — trasporto, guida, pedaggi e parcheggi — è compreso.","question":"L''ingresso è incluso?"},{"answer":"Circa 5–6 km nell''arco della giornata, in gran parte l''anello pianeggiante di 3,2 km attorno al lago, al mattino. Alla cascata di Jaein ci sono scale sul camminamento in discesa verso la pozza. Art Valley è ripido dalla base al bordo della cava, e la monorotaia risolve il problema: si sale in monorotaia e si scende a piedi attraverso il bosco. Questo tour non prevede né escursioni in montagna né salite in vetta.","question":"Quanto si cammina e quanto è impegnativo?"},{"answer":"Non è incluso, circa ₩15.000–20.000. Il pranzo è a Idong, il distretto di Pocheon che dà il nome all''Idong galbi (costine di manzo). I piatti a base di funghi e l''uleong — lumaca d''acqua dolce — sono le altre specialità locali, e il makgeolli di Idong viene prodotto nella stessa valle. Dica alla sua guida se le servono opzioni vegetariane e le indicherà il locale giusto.","question":"Il pranzo è incluso e quali sono le opzioni?"},{"answer":"L''isola di Nami è una singola destinazione, molto popolare, raggiungibile in traghetto. Questo itinerario propone tre paesaggi davvero diversi — un bacino centenario, una gola con cascata basaltica e una cava di granito allagata — in una zona del Gyeonggi che vede una frazione della folla di Nami, con il filo conduttore di un Geoparco mondiale UNESCO che attraversa tutto il pomeriggio.","question":"In che cosa è diverso da una gita di un giorno all''isola di Nami?"},{"answer":"Sì, con qualche compromesso. Il Cheonjuho che gela ad Art Valley è una delle viste più belle del sito, il lago ospita un festival dello slittino e ogni tappa è nel suo momento più tranquillo. Di contro: le giornate sono corte, quindi il pomeriggio è più serrato, e il camminamento della cascata di Jaein può essere ghiacciato. Con l''abbigliamento giusto è un''ottima giornata invernale.","question":"Ne vale la pena in inverno?"},{"answer":"Il tour si svolge comunque. L''anello del lago e Art Valley si affrontano bene con un ombrello, e la pioggia anzi rende più potente la cascata di Jaein. L''unica vera eccezione sono le piogge intense estive, quando i tratti di camminamento della gola possono essere chiusi per sicurezza: in quel caso prolunghiamo le altre tappe invece di annullare la giornata.","question":"Che cosa succede se piove?"},{"answer":"Due punti di ritrovo a Seoul: stazione Hongik University (uscita 8) alle 08:00 e stazione Myeongdong (uscita 2) alle 08:30. La preghiamo di arrivare 10 minuti prima del suo orario di partenza: la guida la attende all''uscita con il bus. Il rientro segue l''ordine inverso: Myeongdong verso le 18:00 e la stazione Hongik University verso le 18:30, a seconda del traffico.","question":"Dove avvengono il ritrovo e il rientro?"},{"answer":"Per la maggior parte, sì. L''anello del lago è pianeggiante e la monorotaia elimina la salita di Art Valley. I due elementi da valutare sono le scale del camminamento alla cascata di Jaein e l''oscillazione del ponte sospeso: entrambi sono facoltativi, e il punto panoramico sul ciglio regala la cascata anche a chi preferisce evitarli. È una giornata di 10 ore, quindi si addice più a viaggiatori anziani attivi che a chi ha bisogno di riposare spesso.","question":"È adatto ai bambini o alle persone anziane?"},{"answer":"Sarebbe difficile. Il lago Sanjeong, la cascata di Jaein e Art Valley si trovano in tre distretti diversi, a cavallo di due contee, e gli autobus per Art Valley passano solo ogni due ore circa. Fare tutte e tre le tappe in una giornata senza un mezzo proprio non è realistico: è gran parte del motivo per cui questo itinerario esiste come tour.","question":"Posso farlo con i mezzi pubblici?"}]'::jsonb;

UPDATE public.tour_product_pages SET
