UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"practicalAccordionItems"}', '[{"id":"departure-days","title":"Дни отправления","preview":"Тур отправляется **только по понедельникам, четвергам и субботам** — пожалуйста, выберите одну из этих дат.","content":["Тур отправляется **только по понедельникам, четвергам и субботам** — пожалуйста, выберите одну из этих дат.","Маршрут, расписание и обе точки посадки одинаковы во все три дня отправления.","Если в ваши даты не попадает понедельник, четверг или суббота, перенести тур на другой день невозможно: это поездка в мини-группе по фиксированному расписанию, а не индивидуальный трансфер."]},{"id":"pickup","title":"Сбор и высадка","preview":"Две точки посадки: станция Хондэ-ипку (выход 8, 08:00) и станция Мёндон (выход 2, 08:30).","content":["Две точки посадки: станция Хондэ-ипку (выход 8, 08:00) и станция Мёндон (выход 2, 08:30).","Пожалуйста, приходите на место встречи за 10 минут до времени отправления.","Гид ждёт у выхода со станции вместе с автобусом.","Высадка идёт в обратном порядке: Мёндон около 18:00, станция Хондэ-ипку около 18:30.","Время возвращения приблизительное и зависит от трафика.","Это групповой формат с фиксированным маршрутом; путешественники добираются до места встречи самостоятельно."]},{"id":"walking","title":"Ходьба и рельеф","preview":"В целом умеренно — около 5–6 км за день, с короткими требовательными участками.","content":["В целом умеренно — около 5–6 км за день, с короткими требовательными участками.","Озеро Санджонхо: ровный круг 3,2 км, без подъёмов, 60–90 мин.","Водопад Чэин: подвесной мост 80 м ровный, но раскачивается; на настиле, спускающемся к котлу, есть лестницы в обе стороны.","Pocheon Art Valley: круто от подножия к кромке — это берёт на себя монорельс; спуск через «Целебный лес» занимает 10–15 мин.","Ни треккинга, ни восхождений на вершины ни на одной остановке.","Рекомендуется удобная закрытая обувь; настил в ущелье бывает мокрым."]},{"id":"weather","title":"Погодная политика","preview":"Сильные сезонные различия; замены обычны","content":["Весна (март–май): Прохладным утром над озером Санджонхо поднимается туман, а талые воды держат водопад Чэин полноводным. Чхонджухо читается самым чистым изумрудом по мере того, как день удлиняется.","Лето (июнь–август): Водопад в самой своей мощи, а в ущелье на несколько градусов прохладнее, чем в городе. Сильные муссонные дожди могут закрыть секции настила у водопада Чэин — единственный погодный риск этого маршрута.","Осень (сентябрь–ноябрь): Самый сильный сезон здесь. Весь октябрь серебряная трава делает склоны Мёнсонсана серебристо-белыми, озеро даёт лучшие отражения года, а гранитные стены Art Valley стоят в полной осенней листве.","Зима (декабрь–февраль): Самое малолюдное время года. Чхонджухо может замёрзнуть, на озере проходит фестиваль катания на санках, а водопад местами обледеневает. Световой день короткий, поэтому вторая половина дня идёт плотнее, а настил у Чэина бывает скользким.","Небольшой дождь: тур, как правило, состоится; сильный дождь может сократить остановки на открытом воздухе"]},{"id":"wear","title":"Что надеть и взять с собой","preview":"Обувь для ходьбы, многослойная одежда и сезонные дополнения","content":["Удобная обувь для ходьбы с хорошим сцеплением","Многослойная одежда с учётом перепадов температуры в горах","Лёгкая куртка или ветровка (прохладнее, чем в центре Сеула, особенно у озера Санджонхо)","Защита от солнца летом; тёплая куртка и перчатки зимой","Фотоаппарат или телефон — на всех трёх остановках отличные кадры"]},{"id":"included","title":"Что включено","preview":"Транспорт из центра Сеула и обратно, лицензированный англоговорящий гид, топливо, дорожные сборы и парковка.","variant":"included","content":["Транспорт из центра Сеула и обратно, лицензированный англоговорящий гид, топливо, дорожные сборы и парковка.","Остановки с бесплатным входом: озеро Санджонхо и его круговая тропа, водопад Чэин, подвесной мост и скайвок.","Не включено — вход в Pocheon Art Valley (≈ ₩6 000 взрослый) и монорельс (≈ ₩5 300 взрослый билет туда-обратно), тарифы 2026 года.","Не включено — обед (≈ ₩15 000–20 000), напитки, личные расходы и чаевые."]},{"id":"geopark","title":"О Всемирном геопарке ЮНЕСКО","preview":"Две сегодняшние остановки имеют статус геосайтов.","content":["Всемирный геопарк ЮНЕСКО Хантанган был сертифицирован 7 июля 2020 года на 209-й сессии Исполнительного совета ЮНЕСКО в Париже и переподтверждён в 2024 году. Он охватывает бассейн реки Хантанган на территории Пхочхона и Ёнчхона в провинции Кёнгидо и Чхорвона в провинции Канвондо.","Водопад Чэин — геосайт: водопад ≈ 18 м над базальтовой столбчатой отдельностью, у основания которой читаются речная эрозионная пещера, котлы-исполины и газовые трубки.","Pocheon Art Valley — геосайт, значащийся как «Art Valley и пхочхонский камень»: древний гранитный фундамент, по которому позже растеклась лава Хантангана.","Всемирный геопарк ЮНЕСКО — это геологический статус; он не то же самое, что включение в список Всемирного наследия ЮНЕСКО."]},{"id":"cancellation","title":"Отмена","preview":"Бесплатная отмена не позднее чем за 24 часа до начала тура.","content":["Бесплатная отмена не позднее чем за 24 часа до начала тура.","Отмена в день тура и неявка возврату не подлежат."]}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'ru'
  AND detail_payload #> '{"practicalAccordionItems"}' IS NOT DISTINCT FROM '[{"id":"pickup","title":"Сбор и высадка","content":["Две точки посадки: станция Хондэ-ипку (выход 8, 08:00) и станция Мёндон (выход 2, 08:30).","Пожалуйста, приходите на место встречи за 10 минут до времени отправления.","Гид ждёт у выхода со станции вместе с автобусом.","Высадка идёт в обратном порядке: Мёндон около 18:00, станция Хондэ-ипку около 18:30.","Время возвращения приблизительное и зависит от трафика.","Это групповой формат с фиксированным маршрутом; путешественники добираются до места встречи самостоятельно."],"preview":"Две точки посадки: станция Хондэ-ипку (выход 8, 08:00) и станция Мёндон (выход 2, 08:30)."},{"id":"walking","title":"Ходьба и рельеф","content":["В целом умеренно — около 5–6 км за день, с короткими требовательными участками.","Озеро Санджонхо: ровный круг 3,2 км, без подъёмов, 60–90 мин.","Водопад Чэин: подвесной мост 80 м ровный, но раскачивается; на настиле, спускающемся к котлу, есть лестницы в обе стороны.","Pocheon Art Valley: круто от подножия к кромке — это берёт на себя монорельс; спуск через «Целебный лес» занимает 10–15 мин.","Ни треккинга, ни восхождений на вершины ни на одной остановке.","Рекомендуется удобная закрытая обувь; настил в ущелье бывает мокрым."],"preview":"В целом умеренно — около 5–6 км за день, с короткими требовательными участками."},{"id":"weather","title":"Погодная политика","content":["Весна (март–май): Прохладным утром над озером Санджонхо поднимается туман, а талые воды держат водопад Чэин полноводным. Чхонджухо читается самым чистым изумрудом по мере того, как день удлиняется.","Лето (июнь–август): Водопад в самой своей мощи, а в ущелье на несколько градусов прохладнее, чем в городе. Сильные муссонные дожди могут закрыть секции настила у водопада Чэин — единственный погодный риск этого маршрута.","Осень (сентябрь–ноябрь): Самый сильный сезон здесь. Весь октябрь серебряная трава делает склоны Мёнсонсана серебристо-белыми, озеро даёт лучшие отражения года, а гранитные стены Art Valley стоят в полной осенней листве.","Зима (декабрь–февраль): Самое малолюдное время года. Чхонджухо может замёрзнуть, на озере проходит фестиваль катания на санках, а водопад местами обледеневает. Световой день короткий, поэтому вторая половина дня идёт плотнее, а настил у Чэина бывает скользким.","Небольшой дождь: тур, как правило, состоится; сильный дождь может сократить остановки на открытом воздухе"],"preview":"Сильные сезонные различия; замены обычны"},{"id":"wear","title":"Что надеть и взять с собой","content":["Удобная обувь для ходьбы с хорошим сцеплением","Многослойная одежда с учётом перепадов температуры в горах","Лёгкая куртка или ветровка (прохладнее, чем в центре Сеула, особенно у озера Санджонхо)","Защита от солнца летом; тёплая куртка и перчатки зимой","Фотоаппарат или телефон — на всех трёх остановках отличные кадры"],"preview":"Обувь для ходьбы, многослойная одежда и сезонные дополнения"},{"id":"included","title":"Что включено","content":["Транспорт из центра Сеула и обратно, лицензированный англоговорящий гид, топливо, дорожные сборы и парковка.","Остановки с бесплатным входом: озеро Санджонхо и его круговая тропа, водопад Чэин, подвесной мост и скайвок.","Не включено — вход в Pocheon Art Valley (≈ ₩6 000 взрослый) и монорельс (≈ ₩5 300 взрослый билет туда-обратно), тарифы 2026 года.","Не включено — обед (≈ ₩15 000–20 000), напитки, личные расходы и чаевые."],"preview":"Транспорт из центра Сеула и обратно, лицензированный англоговорящий гид, топливо, дорожные сборы и парковка.","variant":"included"},{"id":"geopark","title":"О Всемирном геопарке ЮНЕСКО","content":["Всемирный геопарк ЮНЕСКО Хантанган был сертифицирован 7 июля 2020 года на 209-й сессии Исполнительного совета ЮНЕСКО в Париже и переподтверждён в 2024 году. Он охватывает бассейн реки Хантанган на территории Пхочхона и Ёнчхона в провинции Кёнгидо и Чхорвона в провинции Канвондо.","Водопад Чэин — геосайт: водопад ≈ 18 м над базальтовой столбчатой отдельностью, у основания которой читаются речная эрозионная пещера, котлы-исполины и газовые трубки.","Pocheon Art Valley — геосайт, значащийся как «Art Valley и пхочхонский камень»: древний гранитный фундамент, по которому позже растеклась лава Хантангана.","Всемирный геопарк ЮНЕСКО — это геологический статус; он не то же самое, что включение в список Всемирного наследия ЮНЕСКО."],"preview":"Две сегодняшние остановки имеют статус геосайтов."},{"id":"cancellation","title":"Отмена","content":["Бесплатная отмена не позднее чем за 24 часа до начала тура.","Отмена в день тура и неявка возврату не подлежат."],"preview":"Бесплатная отмена не позднее чем за 24 часа до начала тура."}]'::jsonb;

UPDATE public.tour_product_pages SET
  detail_payload = jsonb_set(detail_payload, '{"staticQuestions"}', '[{"question":"Что изменилось в этом туре — разве в него не входил Herb Island?","answer":"Входил. С августа 2026 года маршрут меняет Herb Island на водопад Чэин в Ёнчхоне и добавляет полноценную остановку на местный обед. Причина в том, что водопад Чэин и Pocheon Art Valley — оба геосайты Всемирного геопарка ЮНЕСКО Хантанган, так что день теперь рассказывает одну связную геологическую историю вместо трёх не связанных между собой остановок. Если вам нужен именно Herb Island, свяжитесь с нами до бронирования — мы организуем это отдельно."},{"question":"По каким дням недели проводится тур?","answer":"Тур проводится **только по понедельникам, четвергам и субботам**. Программа во все три дня одинакова, поэтому выбирайте день, который удобнее для вашей поездки. В остальные дни этот продукт недоступен."},{"question":"Почему водопад Чэин и Art Valley — «объекты ЮНЕСКО»?","answer":"Оба имеют статус геосайтов Всемирного геопарка ЮНЕСКО Хантанган, сертифицированного 7 июля 2020 года и переподтверждённого в 2024-м. Это статус геопарка, а не объекта Всемирного наследия ЮНЕСКО — он признаёт геологию бассейна реки Хантанган на территории Пхочхона, Ёнчхона и Чхорвона. Водопад Чэин показывает базальтовую лаву и её столбчатую отдельность; Art Valley — древний гранитный фундамент, по которому эта лава растеклась."},{"question":"Страшно ли идти по подвесному мосту у водопада Чэин? Можно ли его пропустить?","answer":"Он 80 м в длину и 2 м в ширину и действительно раскачивается под ногами — по замыслу, и для большинства гостей в этом вся прелесть. Пропустить его можно полностью: с обзорной точки на краю ущелья водопад виден и без перехода, а настил к котлу — отдельная дорожка. Никого не оставят позади, если вы предпочтёте твёрдую землю."},{"question":"Входит ли входная плата в стоимость?","answer":"Озеро Санджонхо и водопад Чэин бесплатны. Pocheon Art Valley не включён — примерно ₩6 000 за вход плюс около ₩5 300 за взрослый билет на монорельс туда-обратно в 2026 году, для подростков, военнослужащих и детей дешевле. Обед тоже не включён (≈ ₩15 000–20 000). Всё остальное — транспорт, гид, дорожные сборы и парковка — входит в стоимость."},{"question":"Сколько придётся идти пешком и насколько это тяжело?","answer":"Около 5–6 км за день, и большая часть — ровный круг 3,2 км вокруг озера утром. У водопада Чэин есть лестницы на настиле, ведущем вниз к котлу. В Art Valley подъём от подножия к кромке крутой, но эту задачу решает монорельс: наверх вы едете, вниз идёте через лес. Ни треккинга, ни восхождений на вершины в этом туре нет."},{"question":"Включён ли обед и какие есть варианты?","answer":"Не включён, примерно ₩15 000–20 000. Обед проходит в Идоне — пхочхонском районе, давшем имя идон-кальби (говяжьим рёбрышкам). Грибные блюда и улён (пресноводная улитка) — другие местные специалитеты, а идонский макколли варят в той же долине. Скажите гиду, если вам нужны вегетарианские варианты, и он подскажет подходящее заведение."},{"question":"Чем это отличается от поездки на день на остров Нами?","answer":"Остров Нами — одно очень популярное направление, куда добираются на пароме. Этот маршрут — три по-настоящему разных ландшафта: столетнее водохранилище, ущелье с базальтовым водопадом и затопленный гранитный карьер, — в той части провинции Кёнгидо, где людей в разы меньше, чем на Нами, а через всю вторую половину дня проходит нить Всемирного геопарка ЮНЕСКО."},{"question":"Стоит ли ехать зимой?","answer":"Да, с оговорками. Замерзающее Чхонджухо в Art Valley — одно из лучших зрелищ этого места, на озере проходит фестиваль катания на санках, и все остановки максимально тихие. Против: световой день короткий, поэтому вторая половина дня идёт плотнее, а настил у водопада Чэин может обледенеть. Оденьтесь как следует — и это будет сильный зимний день."},{"question":"Что будет, если пойдёт дождь?","answer":"Тур состоится. Круг вокруг озера и Art Valley вполне переносимы с зонтом, а водопаду Чэин дождь идёт только на пользу. Единственное реальное исключение — сильные летние ливни, когда секции настила в ущелье могут закрыть из соображений безопасности; в этом случае мы продлеваем другие остановки, а не отменяем день."},{"question":"Где происходят сбор и высадка?","answer":"Две точки сбора в Сеуле: станция Хондэ-ипку (выход 8) в 08:00 и станция Мёндон (выход 2) в 08:30. Пожалуйста, приходите за 10 минут до своего времени отправления — гид ждёт у выхода вместе с автобусом. Высадка идёт в обратном порядке: Мёндон около 18:00 и станция Хондэ-ипку около 18:30, в зависимости от трафика."},{"question":"Подходит ли тур детям и людям старшего возраста?","answer":"Большинству — да. Круг вокруг озера ровный, а монорельс снимает подъём в Art Valley. Взвесить стоит две вещи: лестницы на настиле у водопада Чэин и раскачивающийся подвесной мост — и то и другое необязательно, а обзорная точка на краю ущелья показывает водопад тем, кто предпочтёт обойтись без них. День длится 10 часов, так что он лучше подходит активным путешественникам старшего возраста, чем тем, кому нужен частый отдых."},{"question":"Можно ли проехать этот маршрут на общественном транспорте?","answer":"Это было бы непросто. Озеро Санджонхо, водопад Чэин и Art Valley находятся в трёх разных районах двух уездов, а автобусы до Art Valley ходят раз в пару часов. Объехать все три за один день без машины нереально — во многом поэтому этот маршрут и существует как тур."}]'::jsonb, true),
  updated_at = NOW()
WHERE slug = 'pocheon-sanjeong-lake-herb-island-art-valley' AND locale = 'ru'
  AND detail_payload #> '{"staticQuestions"}' IS NOT DISTINCT FROM '[{"answer":"Входил. С августа 2026 года маршрут меняет Herb Island на водопад Чэин в Ёнчхоне и добавляет полноценную остановку на местный обед. Причина в том, что водопад Чэин и Pocheon Art Valley — оба геосайты Всемирного геопарка ЮНЕСКО Хантанган, так что день теперь рассказывает одну связную геологическую историю вместо трёх не связанных между собой остановок. Если вам нужен именно Herb Island, свяжитесь с нами до бронирования — мы организуем это отдельно.","question":"Что изменилось в этом туре — разве в него не входил Herb Island?"},{"answer":"Оба имеют статус геосайтов Всемирного геопарка ЮНЕСКО Хантанган, сертифицированного 7 июля 2020 года и переподтверждённого в 2024-м. Это статус геопарка, а не объекта Всемирного наследия ЮНЕСКО — он признаёт геологию бассейна реки Хантанган на территории Пхочхона, Ёнчхона и Чхорвона. Водопад Чэин показывает базальтовую лаву и её столбчатую отдельность; Art Valley — древний гранитный фундамент, по которому эта лава растеклась.","question":"Почему водопад Чэин и Art Valley — «объекты ЮНЕСКО»?"},{"answer":"Он 80 м в длину и 2 м в ширину и действительно раскачивается под ногами — по замыслу, и для большинства гостей в этом вся прелесть. Пропустить его можно полностью: с обзорной точки на краю ущелья водопад виден и без перехода, а настил к котлу — отдельная дорожка. Никого не оставят позади, если вы предпочтёте твёрдую землю.","question":"Страшно ли идти по подвесному мосту у водопада Чэин? Можно ли его пропустить?"},{"answer":"Озеро Санджонхо и водопад Чэин бесплатны. Pocheon Art Valley не включён — примерно ₩6 000 за вход плюс около ₩5 300 за взрослый билет на монорельс туда-обратно в 2026 году, для подростков, военнослужащих и детей дешевле. Обед тоже не включён (≈ ₩15 000–20 000). Всё остальное — транспорт, гид, дорожные сборы и парковка — входит в стоимость.","question":"Входит ли входная плата в стоимость?"},{"answer":"Около 5–6 км за день, и большая часть — ровный круг 3,2 км вокруг озера утром. У водопада Чэин есть лестницы на настиле, ведущем вниз к котлу. В Art Valley подъём от подножия к кромке крутой, но эту задачу решает монорельс: наверх вы едете, вниз идёте через лес. Ни треккинга, ни восхождений на вершины в этом туре нет.","question":"Сколько придётся идти пешком и насколько это тяжело?"},{"answer":"Не включён, примерно ₩15 000–20 000. Обед проходит в Идоне — пхочхонском районе, давшем имя идон-кальби (говяжьим рёбрышкам). Грибные блюда и улён (пресноводная улитка) — другие местные специалитеты, а идонский макколли варят в той же долине. Скажите гиду, если вам нужны вегетарианские варианты, и он подскажет подходящее заведение.","question":"Включён ли обед и какие есть варианты?"},{"answer":"Остров Нами — одно очень популярное направление, куда добираются на пароме. Этот маршрут — три по-настоящему разных ландшафта: столетнее водохранилище, ущелье с базальтовым водопадом и затопленный гранитный карьер, — в той части провинции Кёнгидо, где людей в разы меньше, чем на Нами, а через всю вторую половину дня проходит нить Всемирного геопарка ЮНЕСКО.","question":"Чем это отличается от поездки на день на остров Нами?"},{"answer":"Да, с оговорками. Замерзающее Чхонджухо в Art Valley — одно из лучших зрелищ этого места, на озере проходит фестиваль катания на санках, и все остановки максимально тихие. Против: световой день короткий, поэтому вторая половина дня идёт плотнее, а настил у водопада Чэин может обледенеть. Оденьтесь как следует — и это будет сильный зимний день.","question":"Стоит ли ехать зимой?"},{"answer":"Тур состоится. Круг вокруг озера и Art Valley вполне переносимы с зонтом, а водопаду Чэин дождь идёт только на пользу. Единственное реальное исключение — сильные летние ливни, когда секции настила в ущелье могут закрыть из соображений безопасности; в этом случае мы продлеваем другие остановки, а не отменяем день.","question":"Что будет, если пойдёт дождь?"},{"answer":"Две точки сбора в Сеуле: станция Хондэ-ипку (выход 8) в 08:00 и станция Мёндон (выход 2) в 08:30. Пожалуйста, приходите за 10 минут до своего времени отправления — гид ждёт у выхода вместе с автобусом. Высадка идёт в обратном порядке: Мёндон около 18:00 и станция Хондэ-ипку около 18:30, в зависимости от трафика.","question":"Где происходят сбор и высадка?"},{"answer":"Большинству — да. Круг вокруг озера ровный, а монорельс снимает подъём в Art Valley. Взвесить стоит две вещи: лестницы на настиле у водопада Чэин и раскачивающийся подвесной мост — и то и другое необязательно, а обзорная точка на краю ущелья показывает водопад тем, кто предпочтёт обойтись без них. День длится 10 часов, так что он лучше подходит активным путешественникам старшего возраста, чем тем, кому нужен частый отдых.","question":"Подходит ли тур детям и людям старшего возраста?"},{"answer":"Это было бы непросто. Озеро Санджонхо, водопад Чэин и Art Valley находятся в трёх разных районах двух уездов, а автобусы до Art Valley ходят раз в пару часов. Объехать все три за один день без машины нереально — во многом поэтому этот маршрут и существует как тур.","question":"Можно ли проехать этот маршрут на общественном транспорте?"}]'::jsonb;

